logger = logging.getLogger(__name__)
@effective_user_decorator
@login_required
def send_student_sms(request):
    if request.method != 'POST':
        messages.error(request, "Invalid request method.")
        return render(request, 'all_student_marks.html', {
            'classes': TeacherClass.objects.filter(user=request.effective_user, academicclassyear__active_year=True).order_by('ClassName__class_name')
        })

    # Parse form data
    student_ids_str = request.POST.get('student_ids_hidden', '')
    class_ids_str = request.POST.get('class_ids', '')
    grade_id = request.POST.get('grade_id')
    examination_id = request.POST.get('examination_id')
    custom_message = request.POST.get('message', '')

    # Convert comma-separated student IDs to list
    student_ids = [int(id.strip()) for id in student_ids_str.split(',') if id.strip()] if student_ids_str else []

    # Convert comma-separated class IDs to list
    class_ids = [int(cid.strip()) for cid in class_ids_str.split(',') if cid.strip()] if class_ids_str else []

    # Validate inputs
    if not class_ids or not grade_id or not examination_id:
        messages.error(request, "Classes, grade, or examination not specified.")
        return render(request, 'all_student_marks.html', {
            'classes': TeacherClass.objects.filter(user=request.effective_user, academicclassyear__active_year=True).order_by('ClassName__class_name')
        })

    # Validate classes
    teacherclasses_qs = TeacherClass.objects.filter(
        id__in=class_ids, 
        user=request.effective_user, 
        academicclassyear__active_year=True
    ).select_related('ClassName')
    if teacherclasses_qs.count() != len(set(class_ids)):
        messages.error(request, "One or more selected classes are invalid or inaccessible.")
        return render(request, 'all_student_marks.html', {
            'classes': TeacherClass.objects.filter(user=request.effective_user, academicclassyear__active_year=True).order_by('ClassName__class_name')
        })
    teacherclasses = teacherclasses_qs

    # Fetch necessary objects
    grading_required = get_object_or_404(GradingModel, id=grade_id, user=request.effective_user)
    examination = get_object_or_404(ExaminationName, id=examination_id, user=request.effective_user)
    description = DisplayModel.objects.filter(user=request.effective_user).last()

    if not student_ids:
        messages.error(request, "Please select at least one student.")
        # Prepare context for redirect (simplified, as full context is complex)
        return redirect('all_student_marks')

    # Fetch SMS configuration
    sms_data = get_object_or_404(SmsConfiguration, user=request.effective_user)
    url_required = sms_data.url_required
    source_address = sms_data.source_addr
    username_required = sms_data.username
    pswd = sms_data.pswd

    # Fetch selected students across classes
    students = Student.objects.filter(
        Q(id__in=student_ids) & Q(teacherclass__in=teacherclasses)
    ).prefetch_related('marks')
    if not students.exists():
        messages.error(request, "No valid students selected.")
        return redirect('all_student_marks')

    # Determine level
    is_primary = grading_required.is_primary
    if is_primary:
        level = 'Primary'
    elif grading_required.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'

    # Get filtered subjects across classes
    required_subjects = RequiredSubject.objects.filter(
        user=request.effective_user,
        level=level,
        teacherclass__in=teacherclasses
    ).values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=required_subjects, user=request.effective_user)

    # Fetch composite for A-level
    composite = None
    component_ids_set = set()
    allow_composite = False
    if level == 'Alevel':
        composite = CompositeSubject.objects.filter(user=request.effective_user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            allow_composite = composite.allow_to_use

    # Define grading logic
    show_division = not is_primary
    exclude_subjects_set = set()
    if show_division:
        exclude_subjects_set = set(ExcludeSubject.objects.filter(user=request.effective_user).values_list('exclude_subject_id', flat=True))

    def get_grade(mark_value, grade_thresholds, is_primary):
        if mark_value is None:
            return '-'
        for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
            if mark_value >= threshold:
                return letter_grade
        return 'E' if is_primary else 'F'

    if is_primary:
        grade_thresholds = {
            grading_required.grade_a: 'A',
            grading_required.grade_b: 'B',
            grading_required.grade_c: 'C',
            grading_required.grade_d: 'D',
            grading_required.grade_f: 'E'
        }
        grade_points = {}
        min_subjects_for_division = None
    elif grading_required.is_advance:
        grade_thresholds = {
            grading_required.grade_a: 'A',
            grading_required.grade_b: 'B',
            grading_required.grade_c: 'C',
            grading_required.grade_d: 'D',
            grading_required.grade_e: 'E',
            grading_required.grade_s: 'S',
            grading_required.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
    else:  # O-level
        grade_thresholds = {
            grading_required.grade_a: 'A',
            grading_required.grade_b: 'B',
            grading_required.grade_c: 'C',
            grading_required.grade_d: 'D',
            grading_required.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7

    division_thresholds = [
        {'max': grading_required.division_1, 'label': 'I'},
        {'max': grading_required.division_2, 'label': 'II'},
        {'max': grading_required.division_3, 'label': 'III'},
        {'max': grading_required.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    # Pre-calculate marks and averages for all students in selected classes
    students_marks_evaluation = Student.objects.filter(teacherclass__in=teacherclasses).annotate(
        total_marks=Sum('marks__marks', filter=Q(marks__subject__id__in=required_subjects, marks__examinationname=examination)),
        average_marks=Avg('marks__marks', filter=Q(marks__subject__id__in=required_subjects, marks__examinationname=examination))
    ).order_by('-average_marks')

    marks_evaluation_dict = {
        s.id: {
            'total_marks': s.total_marks or 0,
            'average_marks': s.average_marks or 0,
        } for s in students_marks_evaluation
    }

    # Optimize: Fetch all marks in one query
    all_student_marks = {}
    if subjects.exists():
        for mark_data in Mark.objects.filter(
            student__teacherclass__in=teacherclasses,
            examinationname=examination,
            subject__id__in=required_subjects
        ).values('student_id', 'subject_id', 'marks'):
            sid = mark_data['student_id']
            if sid not in all_student_marks:
                all_student_marks[sid] = {}
            all_student_marks[sid][mark_data['subject_id']] = mark_data['marks']

    # Prepare full student data for positions (marks list not needed for SMS)
    full_student_data = []
    for student in students_marks_evaluation:
        student_marks_dict = all_student_marks.get(student.id, {})

        # Compute all_grades for has_valid_marks from all individual subjects
        all_grades = []
        for subject_id in required_subjects:
            mark_value = student_marks_dict.get(subject_id)
            if mark_value is not None:
                grade = get_grade(mark_value, grade_thresholds, is_primary)
                all_grades.append(grade)
        has_valid_marks = any(grade != '-' for grade in all_grades)

        # Compute grades_for_division
        grades_for_division = []
        if show_division:
            # Non-component subjects
            non_comp_subjects_qs = subjects.exclude(id__in=component_ids_set)
            for subject in non_comp_subjects_qs:
                mark_value = student_marks_dict.get(subject.id)
                if mark_value is not None and subject.id not in exclude_subjects_set:
                    grade = get_grade(mark_value, grade_thresholds, is_primary)
                    grades_for_division.append(grade)

            # Composite group (always add one averaged grade if applicable)
            if component_ids_set:
                component_marks = [student_marks_dict[sid] for sid in component_ids_set if sid in student_marks_dict and student_marks_dict[sid] is not None]
                if component_marks:
                    avg_mark = round(sum(component_marks) / len(component_marks), 2)
                    comp_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                    grades_for_division.append(comp_grade)

        # Calculate division if applicable
        if show_division:
            filtered_grades = [g for g in grades_for_division if g != '-']
            num_valid_subjects = len(filtered_grades)

            if num_valid_subjects < min_subjects_for_division:
                division = "Inc"
                total_points = 0
            else:
                sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:min_subjects_for_division]
                total_points = sum(grade_points[g] for g in sorted_grades)
                division = 'IV'
                for threshold in division_thresholds:
                    if total_points <= threshold['max']:
                        division = threshold['label']
                        break
        else:
            division = "-"
            total_points = "-"

        student_average = marks_evaluation_dict.get(student.id, {}).get('average_marks', 0)
        overall_grade = '-'
        if student_average > 0:
            for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
                if student_average >= threshold:
                    overall_grade = letter_grade
                    break
            if overall_grade == '-':
                overall_grade = 'E' if is_primary else 'F'

        full_student_data.append({
            'id': student.id,
            'fullName': student.fullName or 'Unnamed Student',
            'sex': student.sex or '-',
            'indexNumber': student.indexNumber or '-',
            'total_marks': marks_evaluation_dict.get(student.id, {}).get('total_marks', 0),
            'average_marks': student_average,
            'grade': overall_grade,
            'division': division,
            'total_points': total_points,
            'has_valid_marks': has_valid_marks,
            'teacherclass': {
                'id': student.teacherclass.id,
                'ClassName': student.teacherclass.ClassName.class_name or 'Unnamed Class'
            }
        })

    # Sort full student data and assign positions
    full_student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))
    total_students = len(full_student_data)
    for position, student in enumerate(full_student_data, 1):
        student['position'] = f"{position}/{total_students}"

    # Update marks_evaluation_dict with positions
    for student_data in full_student_data:
        marks_evaluation_dict[student_data['id']]['position'] = student_data['position']

    # Send SMS to selected students
    success_count = 0
    error_messages = []

    for student in students:
        if not student.contact or not isinstance(student.contact, int) or student.contact < 255000000000:
            error_messages.append(f"Invalid or missing contact number for {student.fullName}: {student.contact}")
            logger.warning(f"Invalid contact for {student.fullName}: {student.contact}")
            messages.error(request, f"Invalid or missing contact number for {student.fullName}.")
            continue

        dest_addr = str(student.contact)
        logger.info(f"Sending SMS to {student.fullName} at {dest_addr}")

        # Get student data for this student
        student_info = next((s for s in full_student_data if s['id'] == student.id), None)
        if not student_info:
            error_messages.append(f"No data found for {student.fullName}")
            continue

        # Use pre-fetched marks dict
        student_marks_dict = all_student_marks.get(student.id, {})

        # Build subjects_text based on display logic
        subjects_text_parts = []
        if composite and allow_composite:
            # Non-component + composite
            for subject in subjects.exclude(id__in=component_ids_set):
                mark_value = student_marks_dict.get(subject.id)
                if mark_value is not None:
                    grade = get_grade(mark_value, grade_thresholds, is_primary)
                    subjects_text_parts.append(f"{subject.nameSubject}: {mark_value} ({grade})")
            # Composite
            component_marks = [v for k, v in student_marks_dict.items() if k in component_ids_set and v is not None]
            if component_marks:
                avg_mark = round(sum(component_marks) / len(component_marks), 2)
                comp_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                subjects_text_parts.append(f"{composite.subject_name}: {avg_mark} ({comp_grade})")
        else:
            # All individual subjects
            for subject in subjects:
                mark_value = student_marks_dict.get(subject.id)
                if mark_value is not None:
                    grade = get_grade(mark_value, grade_thresholds, is_primary)
                    subjects_text_parts.append(f"{subject.nameSubject}: {mark_value} ({grade})")

        subjects_text = ", ".join(subjects_text_parts) if subjects_text_parts else "No valid marks available"

        student_average = student_info['average_marks']
        overall_grade = student_info['grade']
        position = student_info['position']
        total_marks = student_info['total_marks']
        division = student_info['division']
        total_points = student_info['total_points']

        header = description.header if description else f"{examination.exam_name} Results"
        body = description.body if description else ""

        # Construct SMS
        sms_parts = [
            header,
            body,
            custom_message,
            f"Results for {examination.exam_name}: {student.fullName}",
            f"Subjects: {subjects_text}",
            f"Total Marks: {total_marks}",
            f"Average: {student_average:.2f}",
            f"Position: {position}",
            f"Grade: {overall_grade}",
        ]
        if show_division:
            sms_parts.extend([f"Division: {division}", f"Points: {total_points}"])

        sms_parts.append("..Powered By InnoBanks.")

        sms_content = "\n".join(sms_parts)

        data = {
            "source_addr": source_address,
            "encoding": 0,
            "message": sms_content,
            "recipients": [{"recipient_id": student.id, "dest_addr": dest_addr}]
        }

        try:
            response = requests.post(url_required, json=data, auth=HTTPBasicAuth(username_required, pswd))
            if response.status_code == 200:
                success_count += 1
                messages.success(request, f"Message sent successfully to {student.fullName}!")
            else:
                error_messages.append(f"Failed to send SMS to {student.fullName}. Error: {response.text}")
                logger.error(f"API response for {student.fullName}: {response.text}")
                messages.error(request, f"Failed to send message to {student.fullName}. Error: {response.text}")
        except requests.RequestException as e:
            error_messages.append(f"Failed to send SMS to {student.fullName}. Exception: {str(e)}")
            logger.error(f"Exception for {student.fullName}: {str(e)}")
            messages.error(request, f"Failed to send message to {student.fullName}. Exception: {str(e)}")

    # Prepare messages for response
    if success_count == len(student_ids):
        messages.success(request, "Messages sent successfully to all selected students!")
    elif success_count > 0:
        messages.warning(request, f"Messages sent to {success_count} of {len(student_ids)} selected students.")
    else:
        messages.error(request, "No messages were sent due to errors.")

    # If AJAX request, return JSON response
    if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
        message_list = []
        for message in messages.get_messages(request):
            message_list.append({
                'message': str(message),
                'tags': message.tags
            })
        return JsonResponse({
            'messages': message_list
        })

    # For non-AJAX, redirect back
    return redirect('all_student_marks')


