@login_required
def required_subjects_view(request):
    # Query all RequiredSubject, Subject, and TeacherClass objects for the user
    required_subjects = RequiredSubject.objects.filter(user=request.user)
    subjects = Subject.objects.filter(user=request.user)
    teacher_classes = TeacherClass.objects.filter(user=request.user)
    
    # Retrieve last selected values from session
    last_subject_id = request.session.get('last_subject_id')
    last_level = request.session.get('last_level')
    last_teacherclass_id = request.session.get('last_teacherclass_id')
    
    if request.method == 'POST':
        logger.debug(f"POST data: {request.POST}")
        subject_id = request.POST.get('subject')
        level = request.POST.get('level')
        teacherclass_id = request.POST.get('teacherclass')
        
        # Updated condition to include 'Primary'
        if subject_id and level in ['Olevel', 'Alevel', 'Primary'] and teacherclass_id:
            try:
                with transaction.atomic():
                    subject = Subject.objects.get(id=subject_id, user=request.user)
                    teacherclass = TeacherClass.objects.get(id=teacherclass_id, user=request.user)
                    required_subject = RequiredSubject(
                        user=request.user, 
                        subject=subject, 
                        level=level,
                        teacherclass=teacherclass
                    )
                    required_subject.save()
                    messages.success(request, f"Subject '{subject.nameSubject}' assigned to {level} in class '{teacherclass}' successfully!")
                    logger.info(f"Assigned subject {subject.nameSubject} to {level} in class {teacherclass} for user {request.user.username}")
                    
                    # Store last selected values in session
                    request.session['last_subject_id'] = subject_id
                    request.session['last_level'] = level
                    request.session['last_teacherclass_id'] = teacherclass_id
                    request.session.modified = True  # Ensure session is saved
                
                return redirect('required_subjects')
            except (Subject.DoesNotExist, TeacherClass.DoesNotExist):
                messages.error(request, "Selected subject or class does not exist or you do not have permission.")
                logger.error(f"Subject {subject_id} or TeacherClass {teacherclass_id} not found for user {request.user.username}")
            except Exception as e:
                messages.error(request, f"Error assigning subject: {str(e)}")
                logger.error(f"Error assigning subject {subject_id}: {str(e)}", exc_info=True)
        else:
            messages.error(request, "Please select a valid subject, level, and class.")
            logger.warning(f"Invalid form data: subject_id={subject_id}, level={level}, teacherclass_id={teacherclass_id}")
    
    context = {
        'required_subjects': required_subjects,
        'subjects': subjects,
        'teacher_classes': teacher_classes,
        'last_subject_id': last_subject_id,
        'last_level': last_level,
        'last_teacherclass_id': last_teacherclass_id,
    }
    return render(request, 'required_subjects.html', context)

