def update_required_subject(request, id):
    required_subject = get_object_or_404(RequiredSubject, id=id, user=request.user)
    subjects = Subject.objects.filter(user=request.user)
    teacher_classes = TeacherClass.objects.filter(user=request.user)
    
    if request.method == 'POST':
        logger.debug(f"POST data: {request.POST}")
        subject_id = request.POST.get('subject')
        level = request.POST.get('level')
        teacherclass_id = request.POST.get('teacherclass')
        
        # Updated condition to include 'Primary'
        if subject_id and level in ['Olevel', 'Alevel', 'Primary'] and teacherclass_id:
            try:
                with transaction.atomic():
                    subject = Subject.objects.get(id=subject_id, user=request.user)
                    teacherclass = TeacherClass.objects.get(id=teacherclass_id, user=request.user)
                    required_subject.subject = subject
                    required_subject.level = level
                    required_subject.teacherclass = teacherclass
                    required_subject.save()
                    messages.success(request, f"Subject '{subject.nameSubject}' updated to {level} in class '{teacherclass}' successfully!")
                    logger.info(f"Updated subject to {subject.nameSubject} for {level} in class {teacherclass} by {request.user.username}")
                return redirect('required_subjects')
            except (Subject.DoesNotExist, TeacherClass.DoesNotExist):
                messages.error(request, "Selected subject or class does not exist or you do not have permission.")
                logger.error(f"Subject {subject_id} or TeacherClass {teacherclass_id} not found for user {request.user.username}")
            except Exception as e:
                messages.error(request, f"Error updating subject: {str(e)}")
                logger.error(f"Error updating subject {id}: {str(e)}", exc_info=True)
        else:
            messages.error(request, "Please select a valid subject, level, and class.")
            logger.warning(f"Invalid update data: subject_id={subject_id}, level={level}, teacherclass_id={teacherclass_id}")
    
    context = {
        'required_subject': required_subject,
        'subjects': subjects,
        'teacher_classes': teacher_classes,
    }
    return render(request, 'update_required_subject.html', context)

@login_required
def delete_required_subject(request, id):
    required_subject = get_object_or_404(RequiredSubject, id=id, user=request.user)
    
    if request.method == 'POST':
        try:
            with transaction.atomic():
                subject_name = required_subject.subject.nameSubject
                required_subject.delete()
                messages.success(request, f"Subject '{subject_name}' deleted successfully!")
                logger.info(f"Deleted subject {subject_name} by {request.user.username}")
            return redirect('required_subjects')
        except Exception as e:
            messages.error(request, f"Error deleting subject: {str(e)}")
            logger.error(f"Error deleting subject {id}: {str(e)}", exc_info=True)
    
    context = {
        'required_subject': required_subject,
    }
    return render(request, 'delete_required_subject.html', context)

