@login_required
def download_pdf(request, class_id, grade_id, report_id='', examination_name_id=None):
    from django.db.models import Q, Sum, Avg
    from django.db.models import Prefetch
    import psutil
    from datetime import datetime
    from reportlab.lib.pagesizes import A4
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from reportlab.lib.units import cm
    from reportlab.platypus import Image as RLImage
    from PIL import Image as PILImage
    import os
    import pandas as pd  # Assuming pd.isna is used
    from django.http import HttpResponse
    from django.shortcuts import redirect, get_object_or_404
    from django.contrib import messages
    import logging
    logger = logging.getLogger(__name__)
    from .models import TeacherClass, GradingModel, DisplayModel, RequiredSubject, Subject, ExaminationName, Student, Mark, Teacher, ExcludeSubject, SourceDocument, RemarkRange, CompositeSubject  # Adjust imports as per your models

    def get_grade(mark_value, grade_thresholds, is_primary):
        if mark_value is None or pd.isna(mark_value):
            return '-'
        for threshold, letter_grade in sorted(grade_thresholds.items(), reverse=True):
            if mark_value >= threshold:
                return letter_grade
        return 'E' if is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent',
            'B': 'Very Good',
            'C': 'Good',
            'D': 'Pass',
            'F': 'Fail',
            '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        if num_valid_subjects < req_subs_for_div:
            return "Inc", '-'
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs_for_div]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    display = DisplayModel.objects.filter(id=report_id, user=request.user).first() if report_id else DisplayModel.objects.filter(user=request.user).first()
    
    examination_name_id = request.POST.get('examination_id', examination_name_id or request.session.get('selected_examination_id'))
    if not examination_name_id:
        messages.error(request, "No examination selected.")
        return redirect('all_student_marks')
    
    examination_name = get_object_or_404(ExaminationName, id=examination_name_id, user=request.user)

    if grading.is_primary:
        level = 'Primary'
    elif grading.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'
    required_subjects = RequiredSubject.objects.filter(user=request.user, level=level,teacherclass_id=class_id)
    subject_ids = required_subjects.values_list('subject_id', flat=True)
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')

    # Set exclude_subjects for O-level and A-level
    exclude_subjects = set()
    if not grading.is_primary:
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))

    # Handle CompositeSubject for A-level
    composite = None
    component_ids_set = set()
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))

    # Determine display_subjects_qs and subjects_list
    if composite and composite.allow_to_use:
        display_subjects_qs = subjects.exclude(id__in=component_ids_set)
        subjects_list = list(display_subjects_qs.values('id', 'nameSubject'))
        if component_ids_set & set(subject_ids):
            subjects_list.append({
                'id': 'composite',
                'nameSubject': composite.subject_name
            })
    else:
        display_subjects_qs = subjects
        subjects_list = list(subjects.values('id', 'nameSubject'))

    mark_filter = Q(subject__in=subjects, examinationname=examination_name)
    
    students = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(mark_filter).select_related('subject', 'examinationname', 'user').prefetch_related('user__teacher_profile'))
    )

    all_marks = Mark.objects.filter(teacherclass=teacherclass, subject__in=subjects, examinationname=examination_name).select_related('user')
    teacher_map = {}
    for mark in all_marks:
        if mark.user_id:
            teacher = Teacher.objects.filter(user=mark.user).first()
            teacher_map[mark.user_id] = teacher.teacherName or mark.user.username if teacher else mark.user.username

    # Set grade_thresholds and other configs
    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'E'
        }
        grade_points = {}  # Not used for primary
        min_subjects_for_division = None
        req_subs_for_div = None
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
        req_subs_for_div = 3
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7
        req_subs_for_div = 7

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.filter(user=request.user)

    response = HttpResponse(content_type='application/pdf')
    exam_suffix = f"_{examination_name.exam_name.replace(' ', '_')}"
    filename = f"student_report_{teacherclass.ClassName or 'Unnamed_Class'}{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    
    # Simplified document margins based on commented code
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []
    
    # Simplified styling based on commented code
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=9)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=5, alignment=TA_CENTER, leading=6)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 7

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    # Load images once outside the loop
    icon = None
    if display and display.image:
        image_path = display.image.path
        logger.debug(f"Checking image file: {image_path}")
        if os.path.exists(image_path) and os.access(image_path, os.R_OK):
            try:
                with PILImage.open(image_path) as img:
                    img.verify()
                logger.debug(f"Image verified successfully: {image_path}")
                icon = RLImage(image_path, width=2*cm, height=2*cm)
                icon.hAlign = 'CENTER'
                logger.debug(f"Successfully loaded image: {image_path}")
            except Exception as e:
                logger.error(f"Error loading DisplayModel image: {str(e)}")

    sig_img = None
    stamp_img = None
    if source_doc:
        sig_path = source_doc.extracted_signature.path if source_doc.extracted_signature else None
        if sig_path and os.path.exists(sig_path) and os.access(sig_path, os.R_OK):
            try:
                with PILImage.open(sig_path) as img:
                    img.verify()
                sig_img = RLImage(sig_path, width=3*cm, height=1.5*cm)
                sig_img.hAlign = 'LEFT'
            except Exception as e:
                logger.error(f"Error loading signature: {str(e)}")

        stamp_path = source_doc.extracted_stamp.path if source_doc.extracted_stamp else None
        if stamp_path and os.path.exists(stamp_path) and os.access(stamp_path, os.R_OK):
            try:
                with PILImage.open(stamp_path) as img:
                    img.verify()
                stamp_img = RLImage(stamp_path, width=2.5*cm, height=2.5*cm)
                stamp_img.hAlign = 'RIGHT'
            except Exception as e:
                logger.error(f"Error loading stamp: {str(e)}")

    # Header
    header_elements = []
    header_text = display.header if display else f"Results for {teacherclass.ClassName or 'Unnamed Class'} - {examination_name.exam_name}"
    header_elements.append(Paragraph(header_text, header_style))
    header_elements.append(Spacer(1, 4))
    header_elements.append(Paragraph(display.body if display else f"Comprehensive Academic Summary - {teacherclass.ClassName}", subheader_style))
    header_elements.append(Spacer(1, 8))

    if icon:
        header_elements.append(icon)
        header_elements.append(Spacer(1, 0.5*cm))

    elements.extend(header_elements)

    if not students.exists() or not subjects.exists():
        no_data_style = ParagraphStyle(
            name='NoData',
            parent=styles['BodyText'],
            fontSize=10,
            textColor=colors.red,
            alignment=TA_CENTER,
            spaceAfter=12,
            fontName='Helvetica-Bold'
        )
        elements.append(Paragraph("No academic data available for this class.", no_data_style))
    else:
        students_marks_evaluation = Student.objects.filter(teacherclass=teacherclass).annotate(
            total_marks=Sum('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination_name)),
            average_marks=Avg('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination_name))
        ).select_related('teacherclass')
        
        student_data = []
        for student in students:
            # Get all marks for this student as dict for easy access (prefetched marks are already for this exam)
            student_marks = list(student.marks.all())  # Use .all() since prefetched and filtered
            student_marks_dict = {m.subject_id: m.marks for m in student_marks}
            has_valid_marks = any(m is not None for m in student_marks_dict.values())

            total_marks = students_marks_evaluation.get(id=student.id).total_marks or 0
            average_marks = students_marks_evaluation.get(id=student.id).average_marks or 0
            marks_list = []
            grades_for_division = []
            
            # Process display subjects
            for subject in display_subjects_qs:
                mark_value = student_marks_dict.get(subject.id)
                grade = get_grade(mark_value, grade_thresholds, grading.is_primary)
                if mark_value is not None:
                    first_mark = next((m for m in student_marks if m.subject_id == subject.id), None)
                    teacher_name = teacher_map.get(first_mark.user_id, '-') if first_mark and first_mark.user_id else '-'
                else:
                    teacher_name = '-'
                
                marks_list.append({
                    'subject_id': subject.id,
                    'subject_name': subject.nameSubject,
                    'mark': mark_value,
                    'grade': grade,
                    'is_excluded': subject.id in exclude_subjects,
                    'teacher_name': teacher_name
                })
                
                # Append to grades_for_division only if not primary and not excluded
                # Skip individual component grades if allow_to_use=False (to avoid double-counting; averaged added later)
                if not grading.is_primary and subject.id not in exclude_subjects:
                    if not (composite and not composite.allow_to_use and subject.id in component_ids_set):
                        grades_for_division.append(grade)

            # Handle composite logic
            if grading.is_advance and composite:
                # Compute teachers and marks for composite
                component_teachers = set()
                component_marks_values = []
                for comp_id in component_ids_set:
                    comp_mark_obj = next((m for m in student_marks if m.subject_id == comp_id), None)
                    if comp_mark_obj:
                        component_marks_values.append(comp_mark_obj.marks)
                        if comp_mark_obj.user_id:
                            component_teachers.add(teacher_map.get(comp_mark_obj.user_id, comp_mark_obj.user.username))
                
                teachers_display = ', '.join(sorted(component_teachers)) if component_teachers else '-'
                
                if composite.allow_to_use:
                    if component_marks_values:
                        avg_mark = round(sum(component_marks_values) / len(component_marks_values), 2)
                        group_grade = get_grade(avg_mark, grade_thresholds, is_primary=False)
                    else:
                        avg_mark = None
                        group_grade = '-'
                    # Add synthetic mark for composite
                    marks_list.append({
                        'subject_id': 'composite',
                        'subject_name': composite.subject_name,
                        'mark': avg_mark,
                        'grade': group_grade,
                        'is_excluded': False,
                        'teacher_name': teachers_display
                    })
                
                # Always add one averaged grade for division (if components have marks)
                if component_marks_values:
                    avg_mark_div = round(sum(component_marks_values) / len(component_marks_values), 2)
                    group_grade_div = get_grade(avg_mark_div, grade_thresholds, is_primary=False)
                    grades_for_division.append(group_grade_div)
                else:
                    grades_for_division.append('-')

            division, total_points = get_division(grades_for_division)
            
            student_data.append({
                'id': student.id,
                'fullName': student.fullName or 'Unnamed Student',
                'sex': student.sex or '-',
                'indexNumber': student.indexNumber or '-',
                'marks': marks_list,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'grade': get_grade(average_marks, grade_thresholds, grading.is_primary),
                'division': division,
                'total_points': total_points,
                'has_valid_marks': has_valid_marks
            })

        # Sort students: complete first, then by average descending (changed from total_marks for consistency)
        student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))

        # CLASS PERFORMANCE SUMMARY section with margins (based on commented code)
        elements.append(Paragraph("Academic Results", subheader_style))
        
        # Build multi-level header conditionally using subjects_list
        header_row1 = [
            'Pos', 
            'Student Name', 
            'Sex', 
            'Index No'
        ]
        for s in subjects_list:
            header_row1.append(s['nameSubject'])
            header_row1.append('')  # Placeholder for span

        header_row1 += ['Total', 'Avg', 'Grade']
        if not grading.is_primary:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '']  # Empty for first four columns
        for _ in subjects_list:
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '']
        if not grading.is_primary:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans for subject names in header_row1
        subject_start_col = 4
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),  # Pos spans two rows
            ('SPAN', (1, 0), (1, 1)),  # Student Name
            ('SPAN', (2, 0), (2, 1)),  # Sex
            ('SPAN', (3, 0), (3, 1)),  # Index No
        ]
        for i in range(len(subjects_list)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))  # Subject spans two columns

        total_columns = len(header_row1)
        subject_end_col = subject_start_col + len(subjects_list) * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),  # Total
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),  # Avg
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),  # Grade
        ]
        if not grading.is_primary:
            table_style_commands += [
                ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),  # Div
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),  # Pts
            ]

        for i, student in enumerate(student_data, 1):
            row = [
                str(i), 
                student['fullName'], 
                student['sex'], 
                student['indexNumber']
            ]
            for subj in subjects_list:
                if subj['id'] == 'composite':
                    # Find the synthetic composite mark
                    mark_info = next((m for m in student['marks'] if m['subject_id'] == 'composite'), None)
                else:
                    mark_info = next((m for m in student['marks'] if m['subject_id'] == subj['id']), None)
                if mark_info:
                    mark_str = f"{mark_info['mark']}" if mark_info['mark'] is not None else '-'
                    grade = mark_info['grade']
                else:
                    mark_str = '-'
                    grade = '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student['total_marks']:.2f}" if student['total_marks'] > 0 else '-',
                f"{student['average_marks']:.2f}" if student['average_marks'] > 0 else '-',
                student['grade'],
            ])
            if not grading.is_primary:
                row.extend([
                    student['division'],
                    str(student['total_points']) if student['total_points'] != '-' else '-'
                ])
            table_data.append(row)

        # Calculate column widths
        available_width = A4[0] - 30
        base_width = available_width / (4 + len(subjects_list) * 2 + 3 + (2 if not grading.is_primary else 0))  # Adjust for columns
        col_widths = (
            [base_width * 0.5] +  # Pos
            [base_width * 2.5] +  # Name
            [base_width * 0.5] +  # Sex
            [base_width * 1.8] +  # Index
            [base_width * 0.45, base_width * 0.45] * len(subjects_list) +  # Mark, Grade
            [base_width * 0.8] * 3  # Total, Avg, Grade
        )
        if not grading.is_primary:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors per cell
        for row_idx, row in enumerate(table_data[2:], start=2):  # Start from body rows
            for subj_idx in range(len(subjects_list)):
                grade_col = 4 + subj_idx * 2 + 1  # Grade column for this subject
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 10))

        # Individual Student Reports (UNCHANGED except for marks_list handling)
        total_students = len(student_data)
        
        for i, student in enumerate(student_data, 1):
            elements.append(PageBreak())
            
            # Individual report header
            individual_header = []
            
            # Header with school logo and info
            header_row = []
            if icon:
                header_row.append(icon)
            else:
                header_row.append(Paragraph("", body_style))
            
            center_content = [
                Paragraph(f"REPORT FORM FOR: {student['fullName']}", header_style),
                Spacer(1, 0.2*cm),
                Paragraph(f"{teacherclass.ClassName} • {examination_name.exam_name}", subheader_style),
                Spacer(1, 0.1*cm),
                Paragraph(f"Academic Year: {datetime.now().year}", body_style)
            ]
            
            header_row.append(center_content)
            header_row.append(Paragraph(f"Page {i} of {total_students}", footer_style))
            
            header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
            header_table.setStyle(TableStyle([
                ('VALIGN', (0, 0), (-1, 0), 'TOP'),
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ]))
            
            elements.append(header_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # Student information section with modern card-like appearance
            left_column = [
                Paragraph("STUDENT INFORMATION", bold_style),
                Paragraph(f"<b>Name:</b> {student['fullName']}", body_style),
                Paragraph(f"<b>Index Number:</b> {student['indexNumber']}", body_style),
                Paragraph(f"<b>Class:</b> {teacherclass.ClassName}", body_style),
            ]
            right_column = [
                Paragraph("ACADEMIC SUMMARY", bold_style),
                Paragraph(f"<b>Total Marks:</b> {student['total_marks']:.0f}" if student['total_marks'] > 0 else "<b>Total Marks:</b> -", body_style),
                Paragraph(f"<b>Average:</b> {student['average_marks']:.1f}" if student['average_marks'] > 0 else "<b>Average:</b> -", body_style),
                Paragraph(f"<b>Overall Grade:</b> {student['grade']}", body_style),
            ]
            
            if grading.is_primary:
                # For primary, append gender to the class paragraph
                left_column[3] = Paragraph(f"<b>Class:</b> {teacherclass.ClassName}<br/><b>Gender:</b> {student['sex']}", body_style)
            else:
                # For non-primary, add separate rows for gender and division
                left_column.append(Paragraph(f"<b>Gender:</b> {student['sex']}", body_style))
                right_column.append(Paragraph(f"<b>Division:</b> {student['division']}", body_style))
            
            info_data = []
            for l, r in zip(left_column, right_column):
                info_data.append([
                    l,
                    "",
                    r
                ])
            
            info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
            info_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
                ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 4),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ]))
            
            elements.append(info_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # Subject performance table
            elements.append(Paragraph("SUBJECT PERFORMANCE DETAILS", subheader_style))
            elements.append(Spacer(1, 0.3*cm))
            
            marks_header = [
                Paragraph('SUBJECT', table_text_style),
                Paragraph('MARK', table_text_style),
                Paragraph('GRADE', table_text_style),
                Paragraph('TEACHER', table_text_style),
                Paragraph('REMARKS', table_text_style)
            ]
            
            marks_table_data = [marks_header]
            valid_marks = [m for m in student['marks'] if m['grade'] != '-']
            
            for mark_info in valid_marks:
                grade_color = get_grade_color(mark_info['grade'])
                remark = get_remark(mark_info['grade'])
                
                grade_style = ParagraphStyle(
                    name=f'IndividualGrade{mark_info["grade"]}',
                    parent=table_text_style,
                    textColor=grade_color,
                    fontName='Helvetica-Bold',
                    alignment=TA_CENTER
                )
                
                row = [
                    Paragraph(mark_info['subject_name'], table_text_style),
                    Paragraph(f"{mark_info['mark']:.1f}", table_text_style),
                    Paragraph(mark_info['grade'], grade_style),
                    Paragraph(mark_info['teacher_name'], table_text_style),
                    Paragraph(remark, table_text_style)
                ]
                marks_table_data.append(row)
            
            if len(valid_marks) == 0:
                marks_table_data.append([
                    Paragraph('No subjects with marks available', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style),
                    Paragraph('-', table_text_style)
                ])
            
            marks_table = Table(marks_table_data, colWidths=[5.5*cm, 2*cm, 2*cm, 3.5*cm, 3*cm], repeatRows=1)
            marks_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 7),
                ('LEADING', (0, 0), (-1, -1), 8),
                ('ROWBACKGROUNDS', (1, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
            ]))
            
            elements.append(marks_table)
            elements.append(Spacer(1, 0.8*cm))
            
            # Performance summary with modern cards
            if grading.is_primary:
                performance_data = [
                    [
                        Paragraph("CLASS RANKING", bold_style),
                        Paragraph("ATTENDANCE STATUS", bold_style)
                    ],
                    [
                        Paragraph(f"Position: {i} of {total_students}", body_style),
                        Paragraph("Regular", body_style)
                    ]
                ]
                col_widths_perf = [6*cm, 6*cm]
            else:
                performance_data = [
                    [
                        Paragraph("CLASS RANKING", bold_style),
                        Paragraph("POINT SUMMARY", bold_style),
                        Paragraph("ATTENDANCE STATUS", bold_style)
                    ],
                    [
                        Paragraph(f"Position: {i} of {total_students}", body_style),
                        Paragraph(f"Total Points: {student['total_points']}", body_style),
                        Paragraph("Regular", body_style)
                    ]
                ]
                col_widths_perf = [4*cm, 4*cm, 4*cm]
            
            performance_table = Table(performance_data, colWidths=col_widths_perf)
            performance_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fa')),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('LEFTPADDING', (0, 0), (-1, -1), 8),
                ('RIGHTPADDING', (0, 0), (-1, -1), 8),
                ('TOPPADDING', (0, 0), (-1, -1), 6),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
            ]))
            
            elements.append(performance_table)
            elements.append(Spacer(1, 0.5*cm))
            
            # General comment with highlighted background
            avg = student['average_marks'] or 0
            remark = "No remark available"
            for r_range in remark_ranges:
                if r_range.contains(avg):
                    remark = r_range.remark
                    break
            
            comment_style = ParagraphStyle(
                name='Comment',
                parent=body_style,
                fontSize=9,
                textColor=colors.HexColor('#2c3e50'),
                backColor=colors.HexColor('#f8f9fa'),
                borderPadding=8,
                alignment=TA_CENTER
            )
            
            elements.append(Paragraph(f"<b>General Comment:</b> {remark}", comment_style))
            elements.append(Spacer(1, 0.8*cm))
            
            # Signature section with modern layout
            signature_data = []
            signature_row = []
            
            if sig_img:
                signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])
            
            signature_row.append(Spacer(1, 2*cm))
            
            if stamp_img:
                signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
            else:
                signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])
            
            signature_data.append(signature_row)
            
            signature_table = Table(signature_data, colWidths=[4*cm, 2*cm, 4*cm])
            signature_table.setStyle(TableStyle([
                ('ALIGN', (0, 0), (0, 0), 'LEFT'),
                ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
                ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
            ]))
            
            elements.append(signature_table)
            elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

    logger.debug(f"Memory usage before PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
    
    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        logger.debug(f"Memory usage after PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
        messages.success(request, 'Professional examination report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('all_student_marks')
@login_required
def generate_annual_final_marks(request, class_id=None, grade_id=None, examination_name_id=None):
    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    classes = TeacherClass.objects.filter(user=request.user, academicclassyear__active_year=True)
    grades = GradingModel.objects.filter(user=request.user)
    examination_names = ExaminationName.objects.filter(user=request.user)
    context = {
        'classes': classes,
        'grades': grades,
        'examination_names': examination_names,
    }

    if request.method != 'POST':
        return render(request, 'generate_annual_final_marks.html', context)

    if not class_id or not grade_id:
        messages.error(request, "Invalid class or grading system selection.")
        return render(request, 'generate_annual_final_marks.html', context)

    try:
        teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user, academicclassyear__active_year=True)
        grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    except:
        messages.error(request, "Invalid class or grading system selection.")
        return render(request, 'generate_annual_final_marks.html', context)

    # Verify teacher authorization
    try:
        teacher_profile = Teacher.objects.get(user=request.user)
        creator = teacher_profile.created_by
    except Teacher.DoesNotExist:
        messages.error(request, "Your account is not linked to a valid teacher profile.")
        return redirect('teacher_dashboard')

    if not creator:
        messages.error(request, "You are not authorized to generate reports.")
        return redirect('teacher_dashboard')

    examination_name = None
    if examination_name_id:
        examination_name = get_object_or_404(ExaminationName, id=examination_name_id, user=request.user)
    context.update({
        'teacherclass': teacherclass,
        'selected_grade_id': grade_id,
        'selected_examination': examination_name,
    })

    level = 'Alevel' if grading.is_advance else 'Olevel'
    required_subject_ids = RequiredSubject.objects.filter(user=request.user, level=level, teacherclass_id=class_id).values_list('subject_id', flat=True)
    subjects_db = Subject.objects.filter(id__in=required_subject_ids, user=request.user).order_by('nameSubject')
    students = Student.objects.filter(teacherclass=teacherclass).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(teacherclass=teacherclass).select_related('subject'))
    )
    if not students.exists():
        messages.error(request, f"No students found for {teacherclass.ClassName}.")
        return render(request, 'generate_annual_final_marks.html', context)

    exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
    grade_thresholds = {
        grading.grade_a: 'A',
        grading.grade_b: 'B',
        grading.grade_c: 'C',
        grading.grade_d: 'D',
        grading.grade_e: 'E' if grading.is_advance else None,
        grading.grade_s: 'S' if grading.is_advance else None,
        grading.grade_f: 'F'
    }
    grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9} if grading.is_advance else {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.filter(user=request.user)

    # Load images once outside the loop for memory optimization
    icon = None
    display = DisplayModel.objects.filter(user=request.user).first()
    if display and display.image:
        image_path = display.image.path
        if os.path.exists(image_path) and os.access(image_path, os.R_OK):
            try:
                with PILImage.open(image_path) as img:
                    img.verify()
                icon = RLImage(image_path, width=2*cm, height=2*cm)
                icon.hAlign = 'CENTER'
            except Exception as e:
                logger.error(f"Error loading DisplayModel image: {str(e)}")

    sig_img = None
    stamp_img = None
    if source_doc:
        sig_path = source_doc.extracted_signature.path if source_doc.extracted_signature else None
        if sig_path and os.path.exists(sig_path) and os.access(sig_path, os.R_OK):
            try:
                with PILImage.open(sig_path) as img:
                    img.verify()
                sig_img = RLImage(sig_path, width=3*cm, height=1.5*cm)
                sig_img.hAlign = 'LEFT'
            except Exception as e:
                logger.error(f"Error loading signature: {str(e)}")

        stamp_path = source_doc.extracted_stamp.path if source_doc.extracted_stamp else None
        if stamp_path and os.path.exists(stamp_path) and os.access(stamp_path, os.R_OK):
            try:
                with PILImage.open(stamp_path) as img:
                    img.verify()
                stamp_img = RLImage(stamp_path, width=2.5*cm, height=2.5*cm)
                stamp_img.hAlign = 'RIGHT'
            except Exception as e:
                logger.error(f"Error loading stamp: {str(e)}")

    def get_grade(mark):
        if mark is None or pd.isna(mark) or mark <= 0:
            return '-'
        for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
            if grade and mark >= threshold:
                return grade
        return 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent',
            'B': 'Very Good',
            'C': 'Good',
            'D': 'Pass',
            'E': 'Poor',
            'S': 'Subsidiary',
            'F': 'Fail',
            '-': '-'
        }
        return remark_map.get(grade, '-')

    def get_division(grades):
        valid_grades = [g for g in grades if g != '-']
        req_subs = 3 if grading.is_advance else 7
        if len(valid_grades) < req_subs:
            return "Inc", 0
        sorted_points = sorted([grade_points[g] for g in valid_grades])[:req_subs]
        total_points = sum(sorted_points)
        for d in division_thresholds:
            if total_points <= d['max']:
                return d['label'], total_points
        return 'IV', total_points

    # Precompute all student data for memory efficiency (avoid repeated queries in loops)
    student_data = []
    for student in students:
        final_marks_list = []
        total_final_marks = 0
        num_subjects = 0
        grades_for_div = []

        for subject in subjects_db:
            marks_for_subject = student.marks.filter(subject=subject)
            final_mark = 0
            if examination_name:
                mark_obj = marks_for_subject.filter(examinationname=examination_name).first()
                final_mark = mark_obj.marks if mark_obj else None
            else:
                if marks_for_subject.exists():
                    aggregation = marks_for_subject.aggregate(average=Avg('marks'))
                    final_mark = aggregation['average'] or None

            if final_mark is not None and final_mark > 0:
                grade = get_grade(final_mark)
                final_marks_list.append({
                    'subject_id': subject.id,
                    'subject_name': subject.nameSubject,
                    'mark': final_mark,
                    'grade': grade,
                    'is_excluded': subject.id in exclude_subjects,
                })
                total_final_marks += final_mark
                num_subjects += 1
                if not (grading.is_advance and subject.id in exclude_subjects):
                    grades_for_div.append(grade)

        if not final_marks_list:
            continue  # Skip students with no marks to avoid empty sections

        avg_marks = total_final_marks / num_subjects if num_subjects > 0 else 0
        has_valid_marks = any(grade != '-' for grade in grades_for_div)
        division, total_points = get_division(grades_for_div)

        student_data.append({
            'id': student.id,
            'fullName': student.fullName or 'Unnamed Student',
            'sex': student.sex or '-',
            'indexNumber': student.indexNumber or '-',
            'marks': final_marks_list,
            'total_marks': total_final_marks,
            'average_marks': avg_marks,
            'grade': get_grade(avg_marks),
            'division': division,
            'total_points': total_points,
            'has_valid_marks': has_valid_marks
        })

    if not student_data:
        messages.error(request, "No valid student data available for report generation.")
        return redirect('generate_annual_final_marks')

    # Sort student data (once, outside PDF build for efficiency)
    student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['total_marks'] if x['total_marks'] else 0))
    for i, data in enumerate(student_data, 1):
        data['position'] = i

    # Generate PDF response
    response = HttpResponse(content_type='application/pdf')
    report_type = examination_name.exam_name.replace(' ', '_') if examination_name else "AnnualReport"
    filename = f"FinalMarks_{teacherclass.ClassName.replace(' ', '_')}_{report_type}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    # Simplified document margins (optimized for content fit)
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []

    # Styles (consistent with download_pdf for well-structured appearance)
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=9)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=5, alignment=TA_CENTER, leading=6)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 7

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    # Header (shared across document)
    header_elements = []
    header_text = display.header if display else f"Annual Final Marks Report for {teacherclass.ClassName}"
    header_elements.append(Paragraph(header_text, header_style))
    header_elements.append(Spacer(1, 4))
    header_elements.append(Paragraph(display.body if display else f"Comprehensive Academic Summary - {teacherclass.ClassName}", subheader_style))
    header_elements.append(Spacer(1, 8))

    if icon:
        header_elements.append(icon)
        header_elements.append(Spacer(1, 0.5*cm))

    elements.extend(header_elements)

    # Class Performance Summary (optimized table with dynamic widths)
    elements.append(Paragraph("Academic Results Summary", subheader_style))
    header = ['Pos', 'Student Name', 'Sex', 'Index No'] + [s.nameSubject for s in subjects_db] + ['Total', 'Avg', 'Grade', 'Div', 'Pts']
    table_data = [header]

    for i, student in enumerate(student_data, 1):
        row = [str(i), student['fullName'], student['sex'], student['indexNumber']]
        for subject in subjects_db:
            mark_info = next((m for m in student['marks'] if m['subject_id'] == subject.id), None)
            if mark_info:
                sub_table = Table([[str(mark_info['mark']) if mark_info['mark'] is not None else '-', mark_info['grade']]],
                                 colWidths=[14, 14], hAlign='CENTER')
                sub_table.setStyle(TableStyle([
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTSIZE', (0, 0), (-1, -1), 5),
                    ('LEADING', (0, 0), (-1, -1), 6),
                    ('TEXTCOLOR', (1, 0), (1, 0), get_grade_color(mark_info['grade'])),
                ]))
                row.append(sub_table)
            else:
                row.append('-')
        row.extend([
            f"{student['total_marks']:.2f}" if student['total_marks'] > 0 else '-',
            f"{student['average_marks']:.2f}" if student['average_marks'] > 0 else '-',
            student['grade'],
            student['division'],
            str(student['total_points']) if student['total_points'] > 0 else '-'
        ])
        table_data.append(row)

    available_width = A4[0] - 30  # Margins
    total_columns = len(table_data[0])
    base_width = available_width / total_columns
    col_widths = ([base_width * 0.5] + [base_width * 2.5] + [base_width * 0.5] + [base_width * 1.8] +
                  [base_width * 0.9] * len(subjects_db) + [base_width * 0.6] * 5)

    summary_table = Table(table_data, colWidths=col_widths, repeatRows=1)
    summary_table.setStyle(TableStyle([
        ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
        ('BACKGROUND', (0, 0), (-1, 0), colors.lightgrey),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('FONTSIZE', (0, 0), (-1, -1), 5),
        ('LEADING', (0, 0), (-1, -1), 6),
        ('BOX', (0, 0), (-1, -1), 1, colors.black),
        ('LEFTPADDING', (0, 0), (-1, -1), 4),
        ('RIGHTPADDING', (0, 0), (-1, -1), 4),
        ('TOPPADDING', (0, 0), (-1, -1), 4),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
    ]))
    elements.append(KeepTogether(summary_table))  # Prevent table splitting
    elements.append(Spacer(1, 10))

    # Individual Student Reports (structured like download_pdf, no empty pages)
    total_students = len(student_data)
    for i, student in enumerate(student_data, 1):
        elements.append(PageBreak())  # New page for each student

        # Individual header (optimized, no redundant loads)
        individual_header = []
        header_row = []
        if icon:
            header_row.append(icon)
        else:
            header_row.append(Paragraph("", body_style))

        center_content = [
            Paragraph(f"ANNUAL REPORT FOR: {student['fullName']}", header_style),
            Spacer(1, 0.2*cm),
            Paragraph(f"{teacherclass.ClassName} • {report_type}", subheader_style),
            Spacer(1, 0.1*cm),
            Paragraph(f"Academic Year: {datetime.now().year}", body_style)
        ]

        header_row.append(center_content)
        header_row.append(Paragraph(f"Page {i} of {total_students}", footer_style))

        header_table = Table([header_row], colWidths=[3*cm, A4[0]-6*cm-40, 3*cm])
        header_table.setStyle(TableStyle([
            ('VALIGN', (0, 0), (-1, 0), 'TOP'),
            ('ALIGN', (0, 0), (0, 0), 'LEFT'),
            ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
        ]))
        individual_header.append(header_row)
        elements.append(header_table)
        elements.append(Spacer(1, 0.5*cm))

        # Student information (card-like, well-structured)
        info_data = [
            [
                Paragraph("STUDENT INFORMATION", bold_style),
                "",
                Paragraph("ACADEMIC SUMMARY", bold_style)
            ],
            [
                Paragraph(f"<b>Name:</b> {student['fullName']}", body_style),
                "",
                Paragraph(f"<b>Total Marks:</b> {student['total_marks']:.0f}" if student['total_marks'] > 0 else "<b>Total Marks:</b> -", body_style)
            ],
            [
                Paragraph(f"<b>Index Number:</b> {student['indexNumber']}", body_style),
                "",
                Paragraph(f"<b>Average:</b> {student['average_marks']:.1f}" if student['average_marks'] > 0 else "<b>Average:</b> -", body_style)
            ],
            [
                Paragraph(f"<b>Class:</b> {teacherclass.ClassName}", body_style),
                "",
                Paragraph(f"<b>Overall Grade:</b> {student['grade']}", body_style)
            ],
            [
                Paragraph(f"<b>Gender:</b> {student['sex']}", body_style),
                "",
                Paragraph(f"<b>Division:</b> {student['division']}", body_style)
            ]
        ]

        info_table = Table(info_data, colWidths=[6*cm, 1*cm, 6*cm])
        info_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (0, 0), colors.HexColor('#f8f9fa')),
            ('BACKGROUND', (2, 0), (2, 0), colors.HexColor('#f8f9fa')),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('LEFTPADDING', (0, 0), (-1, -1), 8),
            ('RIGHTPADDING', (0, 0), (-1, -1), 8),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ]))
        elements.append(info_table)
        elements.append(Spacer(1, 0.5*cm))

        # Subject performance details (styled table)
        elements.append(Paragraph("SUBJECT PERFORMANCE DETAILS", subheader_style))
        elements.append(Spacer(1, 0.3*cm))

        marks_header = [
            Paragraph('SUBJECT', table_text_style),
            Paragraph('MARK', table_text_style),
            Paragraph('GRADE', table_text_style),
            Paragraph('REMARKS', table_text_style)
        ]

        marks_table_data = [marks_header]
        valid_marks = [m for m in student['marks'] if m['grade'] != '-']

        for mark_info in valid_marks:
            grade_color = get_grade_color(mark_info['grade'])
            remark = get_remark(mark_info['grade'])

            grade_style = ParagraphStyle(
                name=f'IndividualGrade{mark_info["grade"]}',
                parent=table_text_style,
                textColor=grade_color,
                fontName='Helvetica-Bold',
                alignment=TA_CENTER
            )

            row = [
                Paragraph(mark_info['subject_name'], table_text_style),
                Paragraph(f"{mark_info['mark']:.1f}", table_text_style),
                Paragraph(mark_info['grade'], grade_style),
                Paragraph(remark, table_text_style)
            ]
            marks_table_data.append(row)

        if not valid_marks:
            marks_table_data.append([
                Paragraph('No subjects with marks available', table_text_style),
                Paragraph('-', table_text_style),
                Paragraph('-', table_text_style),
                Paragraph('-', table_text_style)
            ])

        marks_table = Table(marks_table_data, colWidths=[6*cm, 2*cm, 2*cm, 3*cm], repeatRows=1)
        marks_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2c3e50')),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#dee2e6')),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, -1), 7),
            ('LEADING', (0, 0), (-1, -1), 8),
            ('ROWBACKGROUNDS', (1, 1), (-1, -1), [colors.white, colors.HexColor('#f1f3f5')]),
        ]))
        elements.append(marks_table)
        elements.append(Spacer(1, 0.8*cm))

        # Performance summary (card-like)
        performance_data = [
            [
                Paragraph("CLASS RANKING", bold_style),
                Paragraph("POINT SUMMARY", bold_style),
                Paragraph("ATTENDANCE STATUS", bold_style)
            ],
            [
                Paragraph(f"Position: {student['position']} of {total_students}", body_style),
                Paragraph(f"Total Points: {student['total_points'] if student['total_points'] > 0 else '-'}", body_style),
                Paragraph("Regular", body_style)
            ]
        ]

        performance_table = Table(performance_data, colWidths=[4*cm, 4*cm, 4*cm])
        performance_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#f8f9fa')),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#e9ecef')),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('LEFTPADDING', (0, 0), (-1, -1), 8),
            ('RIGHTPADDING', (0, 0), (-1, -1), 8),
            ('TOPPADDING', (0, 0), (-1, -1), 6),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
        ]))
        elements.append(performance_table)
        elements.append(Spacer(1, 0.5*cm))

        # General comment
        avg = student['average_marks'] or 0
        remark = "No remark available"
        for r_range in remark_ranges:
            if r_range.contains(avg):
                remark = r_range.remark
                break

        comment_style = ParagraphStyle(
            name='Comment',
            parent=body_style,
            fontSize=9,
            textColor=colors.HexColor('#2c3e50'),
            backColor=colors.HexColor('#f8f9fa'),
            borderPadding=8,
            alignment=TA_LEFT
        )

        elements.append(Paragraph(f"<b>General Comment:</b> {remark}", comment_style))
        elements.append(Spacer(1, 0.8*cm))

        # Signature section
        signature_data = []
        signature_row = []

        if sig_img:
            signature_row.append([sig_img, Paragraph("Authorized Signature", footer_style)])
        else:
            signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Authorized Signature", footer_style)])

        signature_row.append(Spacer(1, 2*cm))

        if stamp_img:
            signature_row.append([stamp_img, Paragraph("Official Stamp", footer_style)])
        else:
            signature_row.append([Paragraph("_________________________", bold_style), Paragraph("Official Stamp", footer_style)])

        signature_data.append(signature_row)

        signature_table = Table(signature_data, colWidths=[4*cm, 2*cm, 4*cm])
        signature_table.setStyle(TableStyle([
            ('ALIGN', (0, 0), (0, 0), 'LEFT'),
            ('ALIGN', (2, 0), (2, 0), 'RIGHT'),
            ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
        ]))
        elements.append(signature_table)
        elements.append(Paragraph(f"Generated on: {current_time}", footer_style))

    logger.debug(f"Memory usage before PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    try:
        doc.build(elements, onFirstPage=add_page_number, onLaterPages=add_page_number)
        logger.debug(f"Memory usage after PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
        messages.success(request, 'Annual final marks report generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('generate_annual_final_marks')

@login_required
def merge_term_marks_pdfs(request, class_id=None):
    classes = TeacherClass.objects.filter(user=request.user,academicclassyear__active_year=True)
    grades = GradingModel.objects.filter(user=request.user)

    context = {
        'classes': classes,
        'grades': grades,
    }

    if request.method == 'POST':
        class_id = request.POST.get('class_id')
        grade_id = request.POST.get('grade_id')

        if not class_id or not grade_id or not TeacherClass.objects.filter(id=class_id, user=request.user,academicclassyear__active_year=True).exists() or not GradingModel.objects.filter(id=grade_id, user=request.user).exists():
            messages.error(request, f"Invalid selection: Class ID {class_id} or Grade ID {grade_id}.")
            return render(request, 'merge_term_marks_pdfs.html', context)

        teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user,academicclassyear__active_year=True)
        grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
        context['teacherclass'] = teacherclass
        context['selected_grade_id'] = grade_id

        # Determine level based on is_advance
        level = 'Alevel' if grading.is_advance else 'Olevel'
        
        # Fetch filtered subjects using RequiredSubject
        required_subjects = RequiredSubject.objects.filter(user=request.user, level=level)
        subject_ids = required_subjects.values_list('subject_id', flat=True)
        subjects_db = Subject.objects.filter(id__in=subject_ids, user=request.user)
        subjects_db_dict = {s.nameSubject.lower(): s for s in subjects_db}

        pdf_uploads = TermMarksUpload.objects.filter(
            user=request.user, 
            teacherclass=teacherclass,
            for_merging_pdf=True
        )
        if not pdf_uploads.exists():
            messages.error(request, "No PDFs selected for merging.")
            logger.error(f"No TermMarksUpload objects marked for merging found for user {request.user} and class {teacherclass}.")
            return render(request, 'merge_term_marks_pdfs.html', context)

        if grading.is_advance:
            exclude_subjects = ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject', flat=True)
            grade_thresholds = {
                grading.grade_a: 'A', grading.grade_b: 'B', grading.grade_c: 'C',
                grading.grade_d: 'D', grading.grade_e: 'E', grading.grade_s: 'S', grading.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        else:
            exclude_subjects = []
            grade_thresholds = {
                grading.grade_a: 'A', grading.grade_b: 'B', grading.grade_c: 'C',
                grading.grade_d: 'D', grading.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}

        division_thresholds = [
            {'max': grading.division_1, 'label': 'I'},
            {'max': grading.division_2, 'label': 'II'},
            {'max': grading.division_3, 'label': 'III'},
            {'max': grading.division_4, 'label': 'IV'},
            {'max': float('inf'), 'label': '0'}
        ]

        all_data = []
        subjects_set = set()
        student_data_dict = {}

        for upload in pdf_uploads:
            pdf_path = upload.pdf_file.path
            if not os.path.exists(pdf_path):
                messages.error(request, f"PDF file not found at {pdf_path}.")
                logger.error(f"PDF not found: {pdf_path}")
                continue
                
            try:
                dfs = tabula.read_pdf(pdf_path, pages='all', multiple_tables=True, lattice=True, guess=False)
                if not dfs:
                    messages.error(request, f"No tables found in PDF at {pdf_path}.")
                    logger.error(f"No tables in PDF: {pdf_path}")
                    continue

                pdf_dfs = []
                for i, df in enumerate(dfs):
                    df = df.dropna(how='all')
                    if df.empty:
                        logger.warning(f"Table {i} in PDF {pdf_path} is empty after dropping NA.")
                        continue
                    df.columns = df.columns.str.strip().str.lower()
                    df = df.rename(columns={'s/no': 's_no', 'student name': 'fullname', 'sex': 'sex', 'index no': 'indexnumber'})
                    logger.debug(f"Table {i} in PDF {pdf_path} - Columns: {list(df.columns)}")
                    logger.debug(f"Table {i} in PDF {pdf_path} - Number of students: {len(df)}")
                    pdf_dfs.append(df)

                if not pdf_dfs:
                    messages.error(request, f"No valid tables found in PDF at {pdf_path}.")
                    logger.error(f"No valid tables in PDF: {pdf_path}")
                    continue

                df = pd.concat(pdf_dfs, ignore_index=True)
                logger.debug(f"PDF {pdf_path} - Total students after concatenation: {len(df)}")
                subjects_set.update([col for col in df.columns if col not in ['s_no', 'fullname', 'sex', 'indexnumber', 'total', 'avg', 'grade', 'pos', 'div', 'pts']])
                all_data.append(df)

            except Exception as e:
                messages.error(request, f"Error processing PDF at {pdf_path}: {str(e)}")
                logger.error(f"Error processing PDF {pdf_path}: {str(e)}", exc_info=True)
                continue

        subjects_set = {s for s in subjects_set if s.lower() in subjects_db_dict}  # Filter subjects_set
        if not all_data:
            messages.error(request, "No valid data extracted from selected PDFs.")
            return render(request, 'merge_term_marks_pdfs.html', context)

        def get_grade(mark):
            if mark is None or mark == 0:
                return '-'
            for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
                if mark >= threshold:
                    return grade
            return 'F'

        def get_division(grades_for_division):
            filtered_grades = [g for g in grades_for_division if g != '-']
            num_valid_subjects = len(filtered_grades)
            if grading.is_advance and num_valid_subjects < 3:
                return "Inc", 0
            elif not grading.is_advance and num_valid_subjects < 7:
                return "Inc", 0
            sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:3 if grading.is_advance else 7]
            total_points = sum(grade_points[g] for g in sorted_grades)
            division = 'IV'
            for threshold in division_thresholds:
                if total_points <= threshold['max']:
                    division = threshold['label']
                    break
            return division, total_points

        for df in all_data:
            logger.debug(f"Processing DataFrame with {len(df)} students")
            for _, row in df.iterrows():
                indexnumber = str(row['indexnumber']).strip()
                if indexnumber.lower() == 'nan' or not indexnumber:
                    logger.warning(f"Skipping row with invalid indexnumber: {row.to_dict()}")
                    continue

                if indexnumber not in student_data_dict:
                    student_data_dict[indexnumber] = {
                        'fullname': row['fullname'],
                        'sex': row['sex'],
                        'indexnumber': indexnumber,
                        'marks': {},
                        'total_marks': 0,
                        'subject_count': 0
                    }

                student = student_data_dict[indexnumber]
                
                for subj_name, subject in subjects_db_dict.items():
                    if subj_name in df.columns:
                        mark_raw = str(row[subj_name]).strip()
                        logger.debug(f"Student {row['indexnumber']} - Raw mark for {subj_name}: {mark_raw}")
                        if mark_raw in ['-', ''] or pd.isna(mark_raw):
                            mark = 0
                            grade = '-'
                        else:
                            mark_match = re.match(r'(\d+\.?\d*)\s*([A-FS-])?', mark_raw)
                            if mark_match:
                                mark = float(mark_match.group(1)) if mark_match.group(1) else 0
                                grade = mark_match.group(2) if mark_match.group(2) else get_grade(mark)
                                logger.debug(f"Student {row['indexnumber']} - Parsed mark for {subj_name}: {mark}, Grade: {grade}")
                            else:
                                mark = 0
                                grade = '-'
                                logger.debug(f"Student {row['indexnumber']} - Failed to parse mark for {subj_name}: {mark_raw}")

                        if subject.id not in student['marks']:
                            student['marks'][subject.id] = {
                                'subject_id': subject.id,
                                'subject_name': subject.nameSubject,
                                'mark': mark,
                                'grade': grade,
                                'is_excluded': subject.id in exclude_subjects,
                                'count': 1
                            }
                        else:
                            existing = student['marks'][subject.id]
                            if mark > 0:
                                existing['mark'] = (existing['mark'] * existing['count'] + mark) / (existing['count'] + 1)
                                existing['grade'] = get_grade(existing['mark'])
                                existing['count'] += 1
                            else:
                                existing['grade'] = '-' if existing['mark'] == 0 else get_grade(existing['mark'])

        logger.debug(f"Total unique students after processing all PDFs: {len(student_data_dict)}")

        student_data = []
        for student in student_data_dict.values():
            total_marks = 0
            subject_count = 0
            marks_list = []
            
            for mark_info in student['marks'].values():
                marks_list.append(mark_info)
                if mark_info['mark'] > 0:
                    total_marks += mark_info['mark']
                    subject_count += 1

            student['marks'] = marks_list
            student['total_marks'] = total_marks
            student['average_marks'] = total_marks / subject_count if subject_count > 0 else 0
            student['grade'] = get_grade(student['average_marks'])

            grades_for_division = [m['grade'] for m in marks_list if not m['is_excluded']]
            division, total_points = get_division(grades_for_division)
            student['division'] = division
            student['total_points'] = total_points
            
            student_data.append(student)

        logger.debug(f"Total students in final student_data: {len(student_data)}")

        student_data.sort(key=lambda x: x['average_marks'], reverse=True)
        for i, student in enumerate(student_data, 1):
            student['position'] = i

        response = HttpResponse(content_type='application/pdf')
        filename = f"merged_pdfs_{teacherclass.ClassName}_{datetime.now().strftime('%Y%m%d')}.pdf"
        response['Content-Disposition'] = f'attachment; filename="{filename}"'
        doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
        elements = []
        styles = getSampleStyleSheet()
        header_style = styles['Heading1']
        subheader_style = styles['Heading2']
        body_style = styles['BodyText']
        header_style.alignment = 1
        subheader_style.alignment = 1
        body_style.alignment = 1
        body_style.fontSize = 7

        elements.append(Paragraph(f"Merged PDFs for {teacherclass.ClassName}", header_style))
        elements.append(Spacer(1, 8))

        if not student_data:
            elements.append(Paragraph("No data available to merge.", body_style))
        else:
            overall_data = [['S/No', 'Student Name', 'Sex', 'Index No'] + 
                           [s.nameSubject for s in subjects_db] + 
                           ['Total', 'Avg', 'Grade', 'Pos', 'Div', 'Pts']]
            
            for i, student in enumerate(student_data, 1):
                row = [str(i), student['fullname'] or '-', student['sex'] or '-', student['indexnumber'] or '-']
                for subject in subjects_db:
                    mark_info = next((m for m in student['marks'] if m['subject_id'] == subject.id), None)
                    if mark_info:
                        mark_display = f"{mark_info['mark']:.2f}" if mark_info['mark'] > 0 else '-'
                        grade_display = mark_info['grade']
                        sub_table = Table([[mark_display, grade_display]],
                                        colWidths=[10, 12], hAlign='CENTER')
                        sub_table.setStyle(TableStyle([
                            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                            ('FONTSIZE', (0, 0), (-1, -1), 4),
                            ('LEADING', (0, 0), (-1, -1), 8),
                            ('TEXTCOLOR', (1, 0), (1, 0), colors.red if mark_info['grade'] == 'F' else colors.black),
                        ]))
                        row.append(sub_table)
                    else:
                        row.append('-')
                
                row.extend([
                    f"{student['total_marks']:.2f}" if student['total_marks'] > 0 else '-',
                    f"{student['average_marks']:.2f}" if student['average_marks'] > 0 else '-',
                    student['grade'],
                    str(student['position']),
                    student['division'],
                    student['total_points'] if student['total_points'] > 0 else '-'
                ])
                overall_data.append(row)

            total_columns = len(overall_data[0])
            base_width = (A4[0] - 30) / total_columns
            col_widths = ([base_width * 0.5] + [base_width * 3.0] + [base_width * 0.5] + [base_width * 2.0] +
                          [base_width * 1.0] * len(subjects_db) + [base_width * 0.8] * 6)

            overall_table = Table(overall_data, colWidths=col_widths, splitByRow=True, repeatRows=1)
            overall_table.setStyle(TableStyle([
                ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 6),
                ('LEADING', (0, 0), (-1, -1), 8),
                ('BACKGROUND', (0, 0), (-1, 0), colors.lightgrey),
            ]))
            elements.extend([KeepTogether(overall_table), Spacer(1, 10)])

            # Individual student reports
            for i, student in enumerate(student_data):
                if i > 0:
                    elements.append(PageBreak())
                
                elements.append(Paragraph(f"Student: {student['fullname'] or 'Unnamed Student'}", subheader_style))
                elements.append(Spacer(1, 6))

                student_data_table = [['Subject', 'Marks', 'Grade', 'Teacher', 'Signature', 'Status']]
                grades_for_division = []

                for mark in student['marks']:
                    if mark['mark'] > 0:
                        student_data_table.append([
                            mark['subject_name'] or 'Unnamed',
                            f"{mark['mark']:.2f}",
                            mark['grade'],
                            '',  # Placeholder for Teacher
                            '',  # Placeholder for Signature
                            ''   # Placeholder for Status
                        ])
                        if not mark['is_excluded']:
                            grades_for_division.append(mark['grade'])

                if len(student_data_table) == 1:
                    student_data_table.append(['No subjects with marks available', '-', '-', '', '', ''])

                student_table = Table(student_data_table, colWidths=[120, 40, 40, 60, 60, 60], splitByRow=True, repeatRows=1)
                student_table.setStyle(TableStyle([
                    ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                    ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                    ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                    ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                    ('FONTSIZE', (0, 0), (-1, -1), 6),
                    ('LEADING', (0, 0), (-1, -1), 8),
                    ('BACKGROUND', (0, 0), (-1, 0), colors.lightgrey),
                ]))
                elements.append(student_table)

                overall_grade = student['grade']
                division, total_points = get_division(grades_for_division)
                avg_display = f"{student['average_marks']:.2f}" if student['average_marks'] > 0 else '-'
                total_display = f"{student['total_marks']:.2f}" if student['total_marks'] > 0 else '-'
                points_display = str(total_points) if total_points > 0 else '-'
                summary = f"Position: {student['position']} | Avg: {avg_display} | Total: {total_display} | Division: {division} | Points: {points_display}"
                elements.append(Spacer(1, 6))
                elements.append(Paragraph(summary, body_style))

        elements.append(Spacer(1, 10))
        elements.append(Paragraph(f"Generated on: {datetime.now().strftime('%Y-%m-%d')}", body_style))
        doc.build(elements)
        return response

    if class_id:
        teacherclass = get_object_or_404(TeacherClass, id=class_id, user=request.user,academicclassyear__active_year=True)
        context['teacherclass'] = teacherclass
        context['uploads'] = TermMarksUpload.objects.filter(teacherclass=teacherclass, user=request.user)

    return render(request, 'upload_term_marks.html', context)


from django.http import JsonResponse
from django.contrib.auth.decorators import login_required
from .models import TermMarksUpload,RequiredSubject,Subject

@login_required
def update_merge_selection(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body)
            upload_id = data.get('upload_id')
            for_merging_pdf = data.get('for_merging_pdf')
            
            # Ensure the upload belongs to the user
            upload = get_object_or_404(TermMarksUpload, id=upload_id, user=request.user)
            upload.for_merging_pdf = for_merging_pdf
            upload.save()
            
            return JsonResponse({'success': True})
        except Exception as e:
            logger.error(f"Error updating merge selection: {str(e)}")
            return JsonResponse({'success': False, 'error': str(e)}, status=400)
    return JsonResponse({'success': False, 'error': 'Invalid request method'}, status=405)

    

