from django.contrib.auth.decorators import login_required
from django.http import HttpResponse
from django.shortcuts import get_object_or_404
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER  # Import TA_CENTER for alignment
from reportlab.graphics.shapes import Drawing
from reportlab.graphics.charts.barcharts import VerticalBarChart
from reportlab.graphics.charts.textlabels import Label
from datetime import datetime

from .models import GradingModel, ExaminationName, TeacherClass, Teacher, Subject, Mark, RequiredSubject
@login_required
def download_top_ten_subjects_pdf(request, grade_id, examination_id, class_ids):
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    examination = get_object_or_404(ExaminationName, id=examination_id, user=request.user)
    class_id_list = class_ids.split(',')
    selected_classes = TeacherClass.objects.filter(
        id__in=class_id_list, 
        user=request.user,
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')

    if not selected_classes.exists():
        raise Http404("No valid classes selected.")

    level = 'Primary' if grading.is_primary else 'Alevel' if grading.is_advance else 'Olevel'

    def determine_grade(mark, grading_system):
        if grading_system.is_primary:
            if mark >= grading_system.grade_a: return 'A'
            elif mark >= grading_system.grade_b: return 'B'
            elif mark >= grading_system.grade_c: return 'C'
            elif mark >= grading_system.grade_d: return 'D'
            else: return 'E'
        elif grading_system.is_advance:
            if mark >= grading_system.grade_a: return 'A'
            elif mark >= grading_system.grade_b: return 'B'
            elif mark >= grading_system.grade_c: return 'C'
            elif mark >= grading_system.grade_d: return 'D'
            elif mark >= grading_system.grade_e: return 'E'
            elif mark >= grading_system.grade_s: return 'S'
            else: return 'F'
        else:  # O-Level
            if mark >= grading_system.grade_a: return 'A'
            elif mark >= grading_system.grade_b: return 'B'
            elif mark >= grading_system.grade_c: return 'C'
            elif mark >= grading_system.grade_d: return 'D'
            else: return 'F'

    if not grading.is_primary:
        grade_points = {
            'A': 1.0, 'B': 2.0, 'C': 3.0, 'D': 4.0,
            **({'E': 5.0, 'S': 6.0, 'F': 7.0} if grading.is_advance else {'F': 5.0})
        }
    else:
        grade_points = {}

    subordinate_teacher_user_ids = Teacher.objects.filter(created_by=request.user).values_list('user_id', flat=True)
    all_user_ids = list(subordinate_teacher_user_ids) + [request.user.id]

    subjects_data = []

    # Get unique subjects across all selected classes
    all_required_subjects = RequiredSubject.objects.filter(
        user=request.user, 
        level=level, 
        teacherclass__in=selected_classes
    )
    subjects = Subject.objects.filter(
        id__in=all_required_subjects.values('subject_id').distinct(), 
        user=request.user
    )

    for subject in subjects:
        marks = Mark.objects.filter(
            subject=subject,
            user_id__in=all_user_ids,
            teacherclass__in=selected_classes,  # Filter by all selected classes
            examinationname=examination
        )

        if marks.exists():
            student_count = marks.count()
            if grading.is_primary:
                total_marks = sum(mark.marks for mark in marks)
                performance_score = round(total_marks / student_count, 2) if student_count > 0 else 0.00
                performance_percentage = performance_score  # Already in 0-100 scale
                subjects_data.append({
                    'subject': subject,
                    'performance_score': performance_score,
                    'performance_percentage': performance_percentage
                })
            else:
                total_points = sum(grade_points.get(determine_grade(mark.marks, grading), 0) for mark in marks)
                gpa = round(total_points / student_count, 2) if student_count > 0 else 0.00

                # Convert GPA to percentage
                min_gp = min(grade_points.values())
                max_gp = max(grade_points.values())
                gpa_percentage = round(((max_gp - gpa) / (max_gp - min_gp)) * 100, 2) if max_gp != min_gp else 0.00

                subjects_data.append({
                    'subject': subject,
                    'performance_score': gpa,
                    'performance_percentage': gpa_percentage
                })

    if grading.is_primary:
        sorted_subjects = sorted(subjects_data, key=lambda x: x['performance_score'], reverse=True)[:10]
    else:
        sorted_subjects = sorted(subjects_data, key=lambda x: x['performance_score'])[:10]

    # Create PDF
    response = HttpResponse(content_type='application/pdf')
    class_names = ', '.join([c.ClassName.class_name or 'Unnamed Class' for c in selected_classes])
    response['Content-Disposition'] = f'attachment; filename="top_subjects_{class_names.replace(" ", "_")}_{examination.exam_name}.pdf"'
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=20, leftMargin=20, topMargin=20, bottomMargin=20)
    elements = []
    styles = getSampleStyleSheet()

    # --- MODIFICATION: Center the title style ---
    title_style = styles['Title']
    title_style.alignment = TA_CENTER

    # Header
    elements.append(Paragraph(f"Top 10 Subjects Performance ({level})", title_style))
    elements.append(Paragraph(f"Classes: {class_names}", styles['Normal']))
    elements.append(Paragraph(f"Examination: {examination.exam_name}", styles['Normal']))
    elements.append(Spacer(1, 12))

    # Table
    if sorted_subjects:
        if grading.is_primary:
            # For Primary: 3 columns
            table_data = [["Rank", "Subject", "Average Mark"]]
            for i, data in enumerate(sorted_subjects, 1):
                row = [
                    str(i),
                    data['subject'].nameSubject or "Unnamed",
                    f"{data['performance_score']:.2f}"
                ]
                table_data.append(row)
            col_widths = [40, 220, 80]
        else:
            # For O/A Level: 4 columns
            table_data = [["Rank", "Subject", "GPA", "GPA %"]]
            for i, data in enumerate(sorted_subjects, 1):
                row = [
                    str(i),
                    data['subject'].nameSubject or "Unnamed",
                    f"{data['performance_score']:.2f}",
                    f"{data['performance_percentage']:.2f}%"
                ]
                table_data.append(row)
            col_widths = [40, 180, 80, 80]

        table = Table(table_data, colWidths=col_widths)
        table.setStyle(TableStyle([
            ('GRID', (0, 0), (-1, -1), 1, colors.black),
            ('BACKGROUND', (0, 0), (-1, 0), colors.darkblue),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ]))
        elements.append(table)
        elements.append(Spacer(1, 24))

        # Chart Drawing
        drawing = Drawing(400, 200)
        chart = VerticalBarChart()
        chart.x = 50
        chart.y = 30
        chart.height = 150
        chart.width = 300

        chart.data = [[data['performance_percentage'] for data in sorted_subjects]]
        
        # Using a simplified name for chart labels to prevent overflow
        chart.categoryAxis.categoryNames = [
            (s['subject'].nameSubject[:10] + '..') if len(s['subject'].nameSubject) > 12 else s['subject'].nameSubject 
            for s in sorted_subjects
        ]
        chart.categoryAxis.labels.boxAnchor = 'n' # Anchor labels to the top

        chart.bars[0].fillColor = colors.green
        chart.valueAxis.valueMin = 0
        chart.valueAxis.valueMax = 100
        chart.valueAxis.valueStep = 10

        chart_label = "Average Score (%) per Subject" if grading.is_primary else "Performance Score (%) per Subject"
        label = Label()
        label.setOrigin(200, 180)
        label.boxAnchor = 'n'
        label.setText(chart_label)
        drawing.add(chart)
        drawing.add(label)
        elements.append(drawing)

    else:
        elements.append(Paragraph("No subject performance data found.", styles['Normal']))

    elements.append(Spacer(1, 12))
    elements.append(Paragraph(f"Generated on: {datetime.now().strftime('%Y-%m-%d %H:%M')}", styles['Normal']))
    doc.build(elements)
    return response
    

from django.contrib.auth.decorators import login_required
from django.shortcuts import render, get_object_or_404
from django.http import HttpResponse
from django.contrib import messages
from django.db.models import Avg
from reportlab.lib.pagesizes import A4
