# Assuming determine_grade is defined here or imported; for completeness, define it
def determine_grade(mark, grading):
    if grading.is_primary:
        if mark >= grading.grade_a: return 'A'
        elif mark >= grading.grade_b: return 'B'
        elif mark >= grading.grade_c: return 'C'
        elif mark >= grading.grade_d: return 'D'
        else: return 'E'
    elif grading.is_advance:
        if mark >= grading.grade_a: return 'A'
        elif mark >= grading.grade_b: return 'B'
        elif mark >= grading.grade_c: return 'C'
        elif mark >= grading.grade_d: return 'D'
        elif mark >= grading.grade_e: return 'E'
        elif mark >= grading.grade_s: return 'S'
        else: return 'F'
    else:  # O-Level
        if mark >= grading.grade_a: return 'A'
        elif mark >= grading.grade_b: return 'B'
        elif mark >= grading.grade_c: return 'C'
        elif mark >= grading.grade_d: return 'D'
        else: return 'F'

@login_required
def teacher_profile(request):
    # Fetch the current teacher
    try:
        teacher = Teacher.objects.get(user=request.user)
    except ObjectDoesNotExist:
        messages.error(request, "Teacher profile not found.")
        return redirect('home')

    creator = teacher.created_by if teacher.created_by else request.user

    # Check if the user has any verified OTP
    is_email_verified = EmailVerificationOTP.objects.filter(
        user=request.user, is_verified=True, purpose='verification'
    ).exists()

    # Fetch all ExaminationName for the creator
    exams = ExaminationName.objects.filter(user=creator).order_by('-id')

    # Get filters from GET parameters - FIXED: Use 'examination_filter' consistently
    class_filter = request.GET.get('class_filter')
    grading_filter = request.GET.get('grading_filter', 'O LEVEL')
    examination_filter = request.GET.get('examination_filter')  # FIXED: Changed from 'exam_id'

    # Defaults for exam - if no filter, use first exam if exists
    if not examination_filter and exams.exists():
        examination_filter = exams.first().id
    selected_exam = ExaminationName.objects.filter(id=examination_filter, user=creator).first() if examination_filter else None

    # Fetch available classes for dropdowns - Ensure all assigned classes are shown
    assigned_classes = TeacherClass.objects.filter(
        teachersubject__teacher=teacher
    ).distinct().select_related('ClassName', 'academicclassyear').order_by('ClassName__class_name')

    # unique_levels like in student
    unique_levels = ['PRIMARY', 'O LEVEL', 'A LEVEL']

    # Filter teacher_subjects based on selected class - If no class_filter, show all
    teacher_subjects_qs = TeacherSubject.objects.filter(teacher=teacher).select_related(
        'subject', 'teacherclass', 'teacherclass__academicclassyear', 'teacherclass__ClassName'
    )
    if class_filter:
        teacher_subjects_qs = teacher_subjects_qs.filter(teacherclass_id=class_filter)
    teacher_subjects = teacher_subjects_qs

    # Get distinct subjects (filtered)
    subjects = Subject.objects.filter(
        teachersubject__teacher=teacher,
        teachersubject__teacherclass_id=class_filter if class_filter else None
    ).distinct()

    # Total students (filtered by class if selected) - Show total across all if no filter
    total_students_qs = Student.objects.filter(
        subject_enrollments__subject__in=subjects,
        subject_enrollments__teacherclass__in=[ts.teacherclass for ts in teacher_subjects]
    ).distinct()
    total_students = total_students_qs.count()

    # Determine applied_level for grading
    applied_level = grading_filter

    # Set grading based on applied_level
    is_primary = applied_level == 'PRIMARY'
    is_advance = applied_level == 'A LEVEL'

    grading_kwargs = {'user': creator}
    if is_primary:
        grading_kwargs['is_primary'] = True
        grading_kwargs['is_advance'] = False
    elif is_advance:
        grading_kwargs['is_primary'] = False
        grading_kwargs['is_advance'] = True
    else:  # O-Level
        grading_kwargs['is_primary'] = False
        grading_kwargs['is_advance'] = False

    selected_grading = GradingModel.objects.filter(**grading_kwargs).first()
    if not selected_grading:
        # Fallback to O-Level
        selected_grading = GradingModel.objects.filter(user=creator, is_primary=False, is_advance=False).first()

    level = applied_level
    performance_label = 'Average Marks' if is_primary else 'GPA'

    # Grade points and thresholds based on selected grading
    grade_points = {}
    all_grades = []
    if selected_grading:
        if is_primary:
            grade_thresholds = {
                selected_grading.grade_a: 'A',
                selected_grading.grade_b: 'B',
                selected_grading.grade_c: 'C',
                selected_grading.grade_d: 'D',
                selected_grading.grade_f: 'E'  # Note: grade_f is used for E in primary
            }
            all_grades = ['A', 'B', 'C', 'D', 'E']
        elif is_advance:
            grade_thresholds = {
                selected_grading.grade_a: 'A',
                selected_grading.grade_b: 'B',
                selected_grading.grade_c: 'C',
                selected_grading.grade_d: 'D',
                selected_grading.grade_e: 'E',
                selected_grading.grade_s: 'S',
                selected_grading.grade_f: 'F'
            }
            grade_points = {'A': 1.0, 'B': 2.0, 'C': 3.0, 'D': 4.0, 'E': 5.0, 'S': 6.0, 'F': 7.0}
            all_grades = ['A', 'B', 'C', 'D', 'E', 'S', 'F']
        else:  # O-Level
            grade_thresholds = {
                selected_grading.grade_a: 'A',
                selected_grading.grade_b: 'B',
                selected_grading.grade_c: 'C',
                selected_grading.grade_d: 'D',
                selected_grading.grade_f: 'F'
            }
            grade_points = {'A': 1.0, 'B': 2.0, 'C': 3.0, 'D': 4.0, 'F': 5.0}
            all_grades = ['A', 'B', 'C', 'D', 'F']

    # Calculate per subject data - FIXED: Always calculate for selected_exam if available, else skip detailed calc
    for ts in teacher_subjects:
        ts.grade_counts = {g: 0 for g in all_grades}
        ts.gpa = 0.0
        ts.average_marks = 0.0
        ts.enrolled_count = Student.objects.filter(
            subject_enrollments__subject=ts.subject,
            subject_enrollments__teacherclass=ts.teacherclass
        ).distinct().count()
        ts.student_count = 0

        if selected_grading and selected_exam:  # FIXED: Ensure calculation uses selected_exam
            marks_qs = Mark.objects.filter(
                subject=ts.subject,
                teacherclass=ts.teacherclass,
                user=request.user,
                examinationname=selected_exam  # FIXED: Use selected_exam here
            )
            if marks_qs.exists():
                marks_list = list(marks_qs.values_list('marks', flat=True))
                student_ids = marks_qs.values_list('student', flat=True).distinct()
                ts.student_count = len(student_ids)
                if marks_list:
                    if is_primary:
                        ts.average_marks = round(sum(marks_list) / len(marks_list), 2)
                        grades = [determine_grade(m, selected_grading) for m in marks_list]
                    else:
                        grades = [determine_grade(m, selected_grading) for m in marks_list]
                        points = [grade_points.get(g, max(grade_points.values()) if grade_points else 5.0) for g in grades]
                        ts.gpa = round(sum(points) / len(points), 2)
                    ts.grade_counts = dict(Counter(grades))
                    # Fill missing grades with 0
                    for g in all_grades:
                        if g not in ts.grade_counts:
                            ts.grade_counts[g] = 0
                else:
                    ts.grade_counts = {g: 0 for g in all_grades}

    # Calculate overall averages for selected exam - FIXED: Recalculate based on selected_exam
    num_subjects_with_data = sum(1 for ts in teacher_subjects if ts.student_count > 0)
    exam_average = 0.0
    exam_average_gpa = 0.0
    if num_subjects_with_data > 0:
        if is_primary:
            exam_average = round(sum(ts.average_marks for ts in teacher_subjects if ts.student_count > 0) / num_subjects_with_data, 2)
        else:
            exam_average_gpa = round(sum(ts.gpa for ts in teacher_subjects if ts.student_count > 0) / num_subjects_with_data, 2)

    # All exams average (using selected grading) - This remains across all exams
    all_exams_average = 0.0
    if exams.exists() and selected_grading and len(teacher_subjects) > 0:
        total_sum = 0.0
        num_all_exams_with_data = 0
        for exam in exams:
            exam_sum = 0.0
            num_exam_subjects = 0
            for ts in teacher_subjects:
                marks_qs = Mark.objects.filter(
                    subject=ts.subject,
                    teacherclass=ts.teacherclass,
                    user=request.user,
                    examinationname=exam
                )
                if marks_qs.exists():
                    marks_list = list(marks_qs.values_list('marks', flat=True))
                    if marks_list:
                        if is_primary:
                            subject_avg = round(sum(marks_list) / len(marks_list), 2)
                        else:
                            grades = [determine_grade(m, selected_grading) for m in marks_list]
                            points = [grade_points.get(g, max(grade_points.values()) if grade_points else 5.0) for g in grades]
                            subject_avg = round(sum(points) / len(points), 2)
                        exam_sum += subject_avg
                        num_exam_subjects += 1
            if num_exam_subjects > 0:
                exam_avg = exam_sum / num_exam_subjects
                total_sum += exam_avg
                num_all_exams_with_data += 1
        all_exams_average = round(total_sum / num_all_exams_with_data, 2) if num_all_exams_with_data > 0 else 0.0

    # Teacher position/rank in the selected class (if class and exam selected) - FIXED: Use selected_exam
    teacher_position = None
    total_teachers_in_class = None
    selected_class_obj = None
    if class_filter and examination_filter and selected_grading:
        try:
            selected_class_obj = TeacherClass.objects.get(id=class_filter)
            # Get all teachers in this class
            class_teachers = TeacherSubject.objects.filter(
                teacherclass=selected_class_obj
            ).values_list('teacher', flat=True).distinct()
            teachers_performance = []
            for other_teacher_id in class_teachers:
                other_teacher = Teacher.objects.get(id=other_teacher_id)
                other_ts = TeacherSubject.objects.filter(teacher=other_teacher, teacherclass=selected_class_obj)
                if other_ts.exists():
                    perf_sum = 0.0
                    num_other_subjects = 0
                    for ots in other_ts:
                        marks_qs = Mark.objects.filter(
                            subject=ots.subject,
                            teacherclass=selected_class_obj,
                            user=other_teacher.user,
                            examinationname=selected_exam  # FIXED: Use selected_exam
                        )
                        if marks_qs.exists():
                            marks_list = list(marks_qs.values_list('marks', flat=True))
                            if marks_list:
                                if is_primary:
                                    subject_perf = round(sum(marks_list) / len(marks_list), 2)
                                else:
                                    grades = [determine_grade(m, selected_grading) for m in marks_list]
                                    points = [grade_points.get(g, max(grade_points.values()) if grade_points else 5.0) for g in grades]
                                    subject_perf = round(sum(points) / len(points), 2)
                                perf_sum += subject_perf
                                num_other_subjects += 1
                    if num_other_subjects > 0:
                        avg_perf = perf_sum / num_other_subjects
                        teachers_performance.append((other_teacher, avg_perf))

            # Sort by performance (desc for primary avg, asc for GPA)
            if is_primary:
                sorted_teachers = sorted(teachers_performance, key=lambda x: x[1], reverse=True)
            else:
                sorted_teachers = sorted(teachers_performance, key=lambda x: x[1])

            total_teachers_in_class = len(sorted_teachers)

            # Find position
            teacher_avg_perf = exam_average if is_primary else exam_average_gpa
            for pos, (t, perf) in enumerate(sorted_teachers, 1):
                if t.id == teacher.id:
                    teacher_position = pos
                    break
        except TeacherClass.DoesNotExist:
            pass

    # Prepare chart data (performance: avg or gpa) - FIXED: Use calculated values for selected_exam
    performance_values = [ts.average_marks if is_primary else ts.gpa for ts in teacher_subjects]
    gpa_chart = {
        'labels': [f"{ts.subject.nameSubject} ({ts.teacherclass.ClassName.class_name})" for ts in teacher_subjects],
        'data': [float(v) for v in performance_values]
    }

    # Get attendance data - Assuming StaffAttendance model exists
    attendance_records = StaffAttendance.objects.filter(teacher=teacher).order_by('-date')

    # Create a dict for quick lookup by date
    attendance_by_date = {att.date: att for att in attendance_records}

    # Determine date range
    today = date.today()
    if attendance_records.exists():
        min_date = min(att.date for att in attendance_records)
        max_date = max(att.date for att in attendance_records)
    else:
        min_date = today.replace(day=1)  # Start of current month
        max_date = today

    # Generate all months in the range (including gaps)
    current_date = min_date.replace(day=1)
    monthly_details = []
    while current_date <= max_date:
        year = current_date.year
        month_num = current_date.month
        month_str = current_date.strftime('%B %Y')
        _, num_days = calendar.monthrange(year, month_num)

        days = []
        present_count = 0
        absent_count = 0
        for day_num in range(1, num_days + 1):
            day_date = date(year, month_num, day_num)
            att = attendance_by_date.get(day_date)
            if att:
                status = att.status
                check_in = att.check_in_time
                check_out = att.check_out_time
                if status == 'present':
                    present_count += 1
                elif status == 'absent':
                    absent_count += 1
            else:
                if day_date <= today:
                    status = 'absent'
                    check_in = None
                    check_out = None
                    absent_count += 1
                else:
                    status = '-'
                    check_in = None
                    check_out = None
            days.append({
                'day': day_num,
                'date': day_date,
                'status': status,
                'check_in': check_in,
                'check_out': check_out,
            })

        monthly_details.append({
            'month_str': month_str,
            'year': year,
            'month_num': month_num,
            'days': days,
            'present': present_count,
            'absent': absent_count,
            'total': present_count + absent_count,
        })

        # Move to next month
        next_month = month_num + 1
        next_year = year
        if next_month > 12:
            next_month = 1
            next_year += 1
        current_date = date(next_year, next_month, 1)

    # Sort by month descending
    monthly_details.sort(key=lambda m: datetime.strptime(m['month_str'], '%B %Y'), reverse=True)

    # Overall counts (from actual records only)
    overall_present = sum(1 for att in attendance_records if att.status == 'present')
    overall_absent = sum(1 for att in attendance_records if att.status == 'absent')
    overall_total = len(attendance_records)

    attendance = {
        'present_count': overall_present,
        'absent_count': overall_absent,
        'total_days': overall_total,
        'attendance_data': attendance_records,
    }

    # Get latest display
    display = DisplayModel.objects.filter(user=creator).last()

    # Handle POST request for marks (adjusted for filters)
    if request.method == 'POST':
        # Filter active based on selected class if provided
        active_academic_year = AcademicClassYear.objects.filter(active_year=True).first()
        active_teacher_subjects = TeacherSubject.objects.filter(
            teacher=teacher,
            teacherclass__academicclassyear=active_academic_year
        ).select_related('subject', 'teacherclass', 'teacherclass__academicclassyear')
        if class_filter:
            active_teacher_subjects = active_teacher_subjects.filter(teacherclass_id=class_filter)

        active_subjects = Subject.objects.filter(
            teachersubject__teacher=teacher,
            teachersubject__teacherclass__academicclassyear=active_academic_year
        ).distinct()
        if class_filter:
            active_subjects = active_subjects.filter(teachersubject__teacherclass_id=class_filter)

        students = Student.objects.filter(
            subject_enrollments__subject__in=active_subjects,
            subject_enrollments__teacherclass__academicclassyear=active_academic_year
        ).distinct().select_related('user').order_by('fullName')
        if class_filter:
            students = students.filter(subject_enrollments__teacherclass_id=class_filter)

        # Rest of POST logic (session for exam, saving marks, etc.)
        examination_name_id = request.session.get('selected_examination_id')
        if not examination_name_id:
            messages.error(request, "Please select an examination first.")
            return redirect('select_examination_name', teacher_subject_id=active_teacher_subjects.first().id if active_teacher_subjects.exists() else 0)

        try:
            examination_name = ExaminationName.objects.get(
                id=examination_name_id,
                user=teacher.user
            )
        except ExaminationName.DoesNotExist:
            messages.error(request, "Selected examination name is invalid.")
            if 'selected_examination_id' in request.session:
                del request.session['selected_examination_id']
            return redirect('select_examination_name', teacher_subject_id=active_teacher_subjects.first().id if active_teacher_subjects.exists() else 0)

        marks_saved = False
        for student in students:
            for subject in active_subjects:
                mark_value = request.POST.get(f'marks_{student.id}_{subject.id}')
                if mark_value and mark_value.strip():
                    teacher_subject = TeacherSubject.objects.filter(
                        teacher=teacher, subject=subject, teacherclass__id=class_filter if class_filter else None
                    ).first()
                    if teacher_subject and not teacher_subject.is_restricted:
                        try:
                            mark_value = float(mark_value)
                            if not (0 <= mark_value <= 100):
                                raise ValueError("Marks must be between 0 and 100.")
                            teacher_class = teacher_subject.teacherclass
                            Mark.objects.update_or_create(
                                user=teacher.user,
                                student=student,
                                subject=subject,
                                teacherclass=teacher_class,
                                examinationname=examination_name,
                                defaults={'marks': mark_value}
                            )
                            marks_saved = True
                        except ValueError as e:
                            messages.error(request, f"Invalid mark for {student.fullName or student.user.username} in {subject.nameSubject}: {e}")
                            return redirect('teacher_dashboard')

        if marks_saved:
            messages.success(request, "Marks have been saved successfully!")
        elif not active_subjects.exists():
            messages.info(request, "No subjects assigned to you for an active academic year.")

        # FIXED: Redirect with current filter params to preserve selection
        params = []
        if class_filter:
            params.append(f'class_filter={class_filter}')
        if grading_filter:
            params.append(f'grading_filter={grading_filter}')
        if examination_filter:
            params.append(f'examination_filter={examination_filter}')
        redirect_url = '?' + '&'.join(params) if params else '?'
        return redirect(redirect_url)

    context = {
        'teacher': teacher,
        'teacher_subjects': teacher_subjects,
        'subjects': subjects,
        'assigned_classes': assigned_classes,  # FIXED: All classes shown in dropdown
        'total_students': total_students,
        'is_primary': is_primary,
        'exam_average': exam_average if is_primary else None,
        'exam_average_gpa': exam_average_gpa if not is_primary else None,
        'all_exams_average': all_exams_average,
        'gpa_chart': {
            'labels': json.dumps(gpa_chart['labels'], cls=DjangoJSONEncoder),
            'data': json.dumps(gpa_chart['data'], cls=DjangoJSONEncoder)
        },
        'teacher_position': teacher_position,
        'total_teachers_in_class': total_teachers_in_class,
        'selected_class': selected_class_obj,
        'performance_label': performance_label,
        'all_grades': all_grades,
        'attendance': attendance,
        'monthly_attendance': monthly_details,
        'display': display,
        'is_verified': is_email_verified,
        'exams': exams,
        'selected_exam': selected_exam,
        'unique_levels': unique_levels,
        'class_filter': class_filter,
        'grading_filter': grading_filter,
        'examination_filter': examination_filter,
    }
    return render(request, 'teacher_profile.html', context)

def determine_grade(mark, grading):
    thresholds = grading.get_thresholds()
    if not thresholds:
        return 'F'  # Or handle empty case as needed
    
    sorted_thresholds = sorted(thresholds.items(), key=lambda x: x[0], reverse=True)
    for threshold, grade in sorted_thresholds:
        if mark >= threshold:
            return grade
    
    # Fallback to lowest grade (matches primary 'E' or O/A 'F')
    lowest_grade = list(thresholds.values())[-1] if thresholds else 'F'
    return lowest_grade

@login_required
def change_teacher_photo(request):
    if request.method == 'POST':
        try:
            teacher = Teacher.objects.get(user=request.user)
            if 'photo' in request.FILES:
                teacher.photo = request.FILES['photo']
                teacher.save()
                # Optionally save face encoding if needed
                if teacher.photo:
                    teacher.save_face_encoding()
                messages.success(request, "Profile photo updated successfully.")
            else:
                messages.error(request, "No photo selected.")
        except ObjectDoesNotExist:
            messages.error(request, "Teacher profile not found.")
        return redirect('teacher_profile')  # Redirect to profile after POST
    # For GET: Redirect to profile (avoids 403)
    return redirect('teacher_profile')



