from django.contrib import messages
from django.contrib.auth.decorators import login_required
from django.shortcuts import render, redirect, get_object_or_404
from .models import RemarkRange
from django.conf import settings

@login_required
def manage_remark_ranges(request):
    if request.method == 'POST':
        min_value = request.POST.get('min_value')
        max_value = request.POST.get('max_value')
        remark = request.POST.get('remark')
        
        try:
            min_val = int(min_value)
            max_val = int(max_value)
            if min_val >= max_val:
                raise ValueError("Min value must be less than max value")
            RemarkRange.objects.create(user=request.user, min_value=min_val, max_value=max_val, remark=remark)
            messages.success(request, 'Remark range added successfully.')
        except ValueError as e:
            messages.error(request, f'Invalid input: {str(e)}')
        except Exception as e:
            messages.error(request, 'An error occurred while adding the remark range.')
        
        return redirect('manage_remark_ranges')

    remark_ranges = RemarkRange.objects.filter(user=request.user).order_by('min_value')
    context = {'remark_ranges': remark_ranges}
    return render(request, 'manage_remark_ranges.html', context)

@login_required
def update_remark_range(request, pk):
    remark_range = get_object_or_404(RemarkRange, pk=pk, user=request.user)
    if request.method == 'POST':
        min_value = request.POST.get('min_value')
        max_value = request.POST.get('max_value')
        remark = request.POST.get('remark')
        
        try:
            min_val = int(min_value)
            max_val = int(max_value)
            if min_val >= max_val:
                raise ValueError("Min value must be less than max value")
            remark_range.min_value = min_val
            remark_range.max_value = max_val
            remark_range.remark = remark
            remark_range.save()
            messages.success(request, 'Remark range updated successfully.')
        except ValueError as e:
            messages.error(request, f'Invalid input: {str(e)}')
        except Exception as e:
            messages.error(request, 'An error occurred while updating the remark range.')
        
        return redirect('manage_remark_ranges')
    
    remark_ranges = RemarkRange.objects.filter(user=request.user).order_by('min_value')
    return render(request, 'manage_remark_ranges.html', {'remark_ranges': remark_ranges})

@login_required
def delete_remark_range(request, pk):
    remark_range = get_object_or_404(RemarkRange, pk=pk, user=request.user)
    remark_range.delete()
    messages.success(request, 'Remark range deleted successfully.')
    return redirect('manage_remark_ranges')


