@login_required
def manage_source_document(request):
    doc, created = SourceDocument.objects.get_or_create(user=request.user)
    documents = SourceDocument.objects.filter(user=request.user)  # Fetch only current user's documents

    if request.method == 'POST':
        comment = request.POST.get('comment')
        file_signature = request.FILES.get('file_signature')
        file_stamp = request.FILES.get('file_stamp')
        allow_to_be_used = request.POST.get('allow_to_be_used') == 'on'  # Convert checkbox to boolean

        doc.comment = comment
        doc.allow_to_be_used = allow_to_be_used

        # Handle file uploads
        if file_signature:
            if doc.file_signature:
                doc.file_signature.delete()
            doc.file_signature = file_signature
        if file_stamp:
            if doc.file_stamp:
                doc.file_stamp.delete()
            doc.file_stamp = file_stamp

        # Delete existing extracted images if new files are uploaded
        if file_signature and doc.extracted_signature:
            doc.extracted_signature.delete()
        if file_stamp and doc.extracted_stamp:
            doc.extracted_stamp.delete()

        doc.save()

        # Process signature file
        if file_signature:
            try:
                file_path = get_file_path(file_signature)
                logger.info(f"Processing signature file: {file_path}")
                if extract_signature(doc, file_path, 'signature', 'extracted_signature'):
                    messages.success(request, 'Signature uploaded and extracted successfully.')
                else:
                    messages.warning(request, 'Signature uploaded, but could not extract. Ensure the file contains a clear signature on a white background.')
                # Clean up temporary file
                if not hasattr(file_signature, 'path') and file_path and os.path.exists(file_path):
                    os.unlink(file_path)
            except Exception as e:
                messages.error(request, f'Failed to process signature: {str(e)}. Ensure Poppler is installed for PDF processing.')
                if not hasattr(file_signature, 'path') and file_path and os.path.exists(file_path):
                    os.unlink(file_path)

        # Process stamp file
        if file_stamp:
            try:
                file_path = get_file_path(file_stamp)
                logger.info(f"Processing stamp file: {file_path}")
                if extract_signature(doc, file_path, 'stamp', 'extracted_stamp'):
                    messages.success(request, 'Stamp uploaded and extracted successfully.')
                else:
                    messages.warning(request, 'Stamp uploaded, but could not extract. Ensure the file contains a clear stamp on a white background.')
                # Clean up temporary file
                if not hasattr(file_stamp, 'path') and file_path and os.path.exists(file_path):
                    os.unlink(file_path)
            except Exception as e:
                messages.error(request, f'Failed to process stamp: {str(e)}. Ensure Poppler is installed for PDF processing.')
                if not hasattr(file_stamp, 'path') and file_path and os.path.exists(file_path):
                    os.unlink(file_path)

        if not file_signature and not file_stamp:
            messages.success(request, 'Document details updated successfully.')

        return redirect('manage_source_document')

    context = {'doc': doc, 'documents': documents}
    return render(request, 'manage_source_document.html', context)

def get_file_path(uploaded_file):
    """
    Get the file path for an uploaded file, handling both InMemoryUploadedFile and TemporaryUploadedFile.
    Use .pdf extension for PDF files to ensure pdf2image compatibility.
    """
    if not uploaded_file:
        return None
    if hasattr(uploaded_file, 'path'):
        return uploaded_file.path
    # Handle InMemoryUploadedFile
    suffix = '.pdf' if uploaded_file.name.lower().endswith('.pdf') else '.tmp'
    with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as temp_file:
        for chunk in uploaded_file.chunks():
            temp_file.write(chunk)
        logger.info(f"Temporary file created: {temp_file.name}")
        return temp_file.name

def extract_signature(doc, file_path, doc_type, field_name):
    """
    Extract signature or stamp from the uploaded file.
    Assumes non-white content on white background.
    Handles images and PDFs (converts first page of PDF to image).
    Saves to the specified field (extracted_signature or extracted_stamp).
    """
    try:
        if not file_path or not os.path.exists(file_path):
            logger.warning(f"File path does not exist: {file_path}")
            return False

        # Handle PDF or image
        if file_path.lower().endswith('.pdf'):
            logger.info(f"Converting PDF to image: {file_path}")
            try:
                images = convert_from_path(file_path)
                if not images:
                    logger.warning(f"No pages found in {doc_type} PDF.")
                    return False
                img = images[0]  # Use first page
            except Exception as e:
                logger.error(f"PDF conversion failed for {doc_type}: {str(e)}")
                return False
        else:
            try:
                img = Image.open(file_path)
            except Exception as e:
                logger.error(f"Failed to open image for {doc_type}: {str(e)}")
                return False

        # Convert to RGBA
        img = img.convert('RGBA')
        data = np.array(img)

        # Log image properties for debugging
        logger.info(f"{doc_type.capitalize()} image shape: {data.shape}")
        logger.info(f"Max RGB values: {data[:,:,0].max()}, {data[:,:,1].max()}, {data[:,:,2].max()}")
        logger.info(f"Min RGB values: {data[:,:,0].min()}, {data[:,:,1].min()}, {data[:,:,2].min()}")

        # Find non-white pixels (lowered threshold to 200)
        non_white = ~((data[:,:,0] > 200) & (data[:,:,1] > 200) & (data[:,:,2] > 200))

        if not np.any(non_white):
            logger.warning(f"No non-white content detected in {doc_type}. All pixels above RGB(200, 200, 200).")
            return False

        # Find bounding box
        rows = np.any(non_white, axis=1)
        cols = np.any(non_white, axis=0)
        ymin = np.where(rows)[0][0]
        ymax = np.where(rows)[0][-1]
        xmin = np.where(cols)[0][0]
        xmax = np.where(cols)[0][-1]

        cropped_data = data[ymin:ymax+1, xmin:xmax+1]

        # Set near-white to transparent
        alpha = np.where((cropped_data[:,:,0] > 200) & (cropped_data[:,:,1] > 200) & (cropped_data[:,:,2] > 200), 0, 255)
        cropped_data[:,:,3] = alpha

        cropped_img = Image.fromarray(cropped_data)

        # Save to the specified field
        buffer = BytesIO()
        cropped_img.save(buffer, format='PNG')
        buffer.seek(0)

        file_name = f"extracted_{doc_type}_{doc.user.username}.png"
        getattr(doc, field_name).save(file_name, buffer)
        doc.save()

        logger.info(f"{doc_type.capitalize()} extracted for user {doc.user.username}")
        return True

    except Exception as e:
        logger.error(f"Error extracting {doc_type} for user {doc.user.username}: {str(e)}")
        return False

