logger = logging.getLogger(__name__)

def get_grade(mark_value, grade_thresholds, is_primary=False):
    if mark_value is None or pd.isna(mark_value):
        return '-'
    for threshold in sorted(grade_thresholds.keys(), reverse=True):
        if mark_value >= threshold:
            return grade_thresholds[threshold]
    return 'E' if is_primary else 'F'

@login_required
def division_summary(request):
    classes = TeacherClass.objects.filter(
        user=request.user, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')
    grades = GradingModel.objects.filter(user=request.user)
    examinations = ExaminationName.objects.filter(user=request.user)
    
    if request.method == 'POST':
        class_ids = request.POST.getlist('class_id')
        grade_id = request.POST.get('grade_id')
        examination_id = request.POST.get('examination_id')
        
        if not class_ids or not grade_id or not examination_id:
            messages.error(request, "Please select at least one class, grading system, and examination.")
            return render(request, 'division_summary_form.html', {
                'classes': classes,
                'grades': grades,
                'examinations': examinations
            })
        
        try:
            grade_id = int(grade_id)
            examination_id = int(examination_id)
            class_ids = [int(cid) for cid in class_ids]
        except ValueError:
            messages.error(request, "Invalid selection. Please choose valid options.")
            return render(request, 'division_summary_form.html', {
                'classes': classes,
                'grades': grades,
                'examinations': examinations
            })
        
        selected_classes = TeacherClass.objects.filter(
            id__in=class_ids, 
            user=request.user, 
            academicclassyear__active_year=True
        ).select_related('ClassName', 'academicclassyear')
        
        if not selected_classes.exists():
            messages.error(request, "No valid classes selected.")
            return render(request, 'division_summary_form.html', {
                'classes': classes,
                'grades': grades,
                'examinations': examinations
            })
        
        grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
        examination_name = get_object_or_404(ExaminationName, id=examination_id, user=request.user)
        
        level = 'Alevel' if grading.is_advance else 'Olevel' if not grading.is_primary else 'Primary'
        required_subjects = RequiredSubject.objects.filter(user=request.user, level=level, teacherclass__in=selected_classes)
        subject_ids = required_subjects.values_list('subject_id', flat=True).distinct()
        subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')
        
        # Handle CompositeSubject for A-Level
        composite = None
        component_ids_set = set()
        display_subjects_qs = subjects
        if grading.is_advance:
            composite = CompositeSubject.objects.filter(user=request.user).first()
            if composite:
                component_ids_set = set(composite.subjects.values_list('id', flat=True))
                if composite.allow_to_use:
                    display_subjects_qs = subjects.exclude(id__in=component_ids_set)
                else:
                    display_subjects_qs = subjects
        
        mark_filter = Q(subject__in=subjects, examinationname=examination_name)
        students = Student.objects.filter(teacherclass__in=selected_classes).prefetch_related(
            Prefetch('marks', queryset=Mark.objects.filter(mark_filter).select_related('subject', 'examinationname', 'user'))
        )
        
        # Define grade thresholds and points
        if grading.is_primary:
            exclude_subjects = set()
            grade_thresholds = {
                grading.grade_a: 'A',
                grading.grade_b: 'B',
                grading.grade_c: 'C',
                grading.grade_d: 'D',
                grading.grade_f: 'E'
            }
            grade_points = {}  # Not used for primary
        elif grading.is_advance:
            exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
            grade_thresholds = {
                grading.grade_a: 'A',
                grading.grade_b: 'B',
                grading.grade_c: 'C',
                grading.grade_d: 'D',
                grading.grade_e: 'E',
                grading.grade_s: 'S',
                grading.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        else:  # O-level
            exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
            grade_thresholds = {
                grading.grade_a: 'A',
                grading.grade_b: 'B',
                grading.grade_c: 'C',
                grading.grade_d: 'D',
                grading.grade_f: 'F'
            }
            grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        
        if not grading.is_primary:
            division_thresholds = [
                {'max': grading.division_1, 'label': 'I'},
                {'max': grading.division_2, 'label': 'II'},
                {'max': grading.division_3, 'label': 'III'},
                {'max': grading.division_4, 'label': 'IV'},
                {'max': float('inf'), 'label': '0'}
            ]
        else:
            division_thresholds = []
        
        def get_division(grades_for_division):
            if grading.is_primary:
                return None, None
            filtered_grades = [g for g in grades_for_division if g != '-']
            num_valid_subjects = len(filtered_grades)
            req_subs = 3 if grading.is_advance else 7
            if num_valid_subjects < req_subs:
                return "Inc", 0
            sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
            total_points = sum(grade_points[g] for g in sorted_grades)
            for threshold in division_thresholds:
                if total_points <= threshold['max']:
                    return threshold['label'], total_points
            return 'IV', total_points
        
        # Calculate data based on grading type
        if grading.is_primary:
            # For primary: Average marks per subject across all classes
            subject_averages = {}
            for subject in display_subjects_qs:
                all_marks_in_subject = []
                for student in students:
                    mark_obj = student.marks.filter(subject=subject, examinationname=examination_name).first()
                    if mark_obj:
                        all_marks_in_subject.append(mark_obj.marks)
                valid_marks = [m for m in all_marks_in_subject if m is not None and not pd.isna(m)]
                avg = sum(valid_marks) / len(valid_marks) if valid_marks else 0
                subject_averages[subject.nameSubject or 'Unnamed'] = round(avg, 2)
            
            summary_data = subject_averages
            summary_type = 'subject_averages'
            division_list = None
        else:
            # For non-primary: Division counts across all classes
            division_counts = {'I': 0, 'II': 0, 'III': 0, 'IV': 0, 'Inc': 0, '0': 0}
            for student in students:
                student_marks_dict = {m.subject_id: m.marks for m in student.marks.all()}
                grades_for_division = []
                for subject in display_subjects_qs:
                    skip_subject = False
                    if (composite and not composite.allow_to_use and subject.id in component_ids_set):
                        skip_subject = True
                    if not skip_subject:
                        mark_value = student_marks_dict.get(subject.id)
                        grade = get_grade(mark_value, grade_thresholds, is_primary=grading.is_primary)
                        if subject.id not in exclude_subjects:
                            grades_for_division.append(grade)
                
                # Handle composite for division
                if composite:
                    component_marks = [student_marks_dict.get(sid) for sid in component_ids_set]
                    valid_comp_marks = [m for m in component_marks if m is not None and not pd.isna(m)]
                    if valid_comp_marks:
                        avg_mark = round(sum(valid_comp_marks) / len(valid_comp_marks), 2)
                        comp_grade = get_grade(avg_mark, grade_thresholds, is_primary=grading.is_primary)
                        # For allow_to_use=True: add as separate
                        # For False: already skipped individuals, add here
                        # But for True, since display excludes, add here
                        # Wait, for both cases, add the comp_grade once
                        # But for allow_to_use=False, since individuals skipped, add comp
                        # For True, add comp in addition to others
                        # No: for True, loop over non-comp, so add comp after
                        # For False, skip comp individuals, add comp after
                        # So yes, add in both cases after loop
                        grades_for_division.append(comp_grade)
                
                division, total_points = get_division(grades_for_division)
                division_counts[division] += 1
            
            total_students = sum(division_counts.values())
            division_counts['subject'] = 'Total'
            division_counts['total_students'] = total_students
            
            summary_data = division_counts
            summary_type = 'division_counts'
            division_list = ['I', 'II', 'III', 'IV', 'Inc', '0']
        
        # Store selected IDs in session for PDF download
        selected_class_ids = ','.join(str(cid) for cid in class_ids)
        request.session['selected_class_ids'] = selected_class_ids
        request.session['selected_grade_id'] = grade_id
        request.session['selected_examination_id'] = examination_id
        
        context = {
            'summary_data': summary_data,
            'summary_type': summary_type,
            'selected_classes': selected_classes,
            'grading_system': grading,
            'examination': examination_name,
            'level': level,
            'classes': classes,
            'grades': grades,
            'examinations': examinations,
            'division_list': division_list,
            'subjects': display_subjects_qs if grading.is_primary else None,
            'selected_class_ids': selected_class_ids
        }
        
        return render(request, 'division_summary.html', context)
    
    return render(request, 'division_summary_form.html', {
        'classes': classes,
        'grades': grades,
        'examinations': examinations
    })

@login_required
def subject_grade_distribution(request):
    # Initial data for the selection form
    grades = GradingModel.objects.filter(user=request.user)
    classes = TeacherClass.objects.filter(
        user=request.user, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')
    examinations = ExaminationName.objects.filter(user=request.user)
    context = {'grades': grades, 'classes': classes, 'examinations': examinations}

    if request.method == 'POST':
        class_ids = request.POST.getlist('class_id')
        grade_id = request.POST.get('grade_id')
        examination_id = request.POST.get('examination_id')

        # Input validation
        if not class_ids or not grade_id or not examination_id:
            messages.error(request, "You must select at least one class, a grading system, and an examination.")
            return render(request, 'subject_grade_distribution.html', context)

        try:
            grade_id = int(grade_id)
            examination_id = int(examination_id)
            class_ids = [int(cid) for cid in class_ids]
        except ValueError:
            messages.error(request, "Invalid selection. Please choose valid options.")
            return render(request, 'subject_grade_distribution.html', context)

        selected_classes = TeacherClass.objects.filter(
            id__in=class_ids, 
            user=request.user, 
            academicclassyear__active_year=True
        ).select_related('ClassName', 'academicclassyear')

        if not selected_classes.exists():
            messages.error(request, "No valid classes selected.")
            return render(request, 'subject_grade_distribution.html', context)

        selected_class_ids_list = list(selected_classes.values_list('id', flat=True))

        grading_required = get_object_or_404(GradingModel, id=grade_id, user=request.user)
        examination = get_object_or_404(ExaminationName, id=examination_id, user=request.user)

        # Determine level for filtering
        level_str = 'Alevel' if grading_required.is_advance else 'Olevel' if not grading_required.is_primary else 'Primary'
        level = 'A-Level' if grading_required.is_advance else 'O-Level' if not grading_required.is_primary else 'Primary'

        # Get required subjects for all selected classes and level
        required_subjects = RequiredSubject.objects.filter(
            user=request.user,
            teacherclass__in=selected_classes,
            level=level_str
        )

        if not required_subjects.exists():
            messages.warning(request, f"No required subjects configured for selected classes at {level}.")
            context.update({
                'selected_classes': selected_classes,
                'selected_examination': examination,
                'selected_class_ids_list': selected_class_ids_list
            })
            return render(request, 'subject_grade_distribution.html', context)

        required_subject_ids = required_subjects.values_list('subject_id', flat=True).distinct()

        # Handle CompositeSubject for A-Level
        composite = None
        component_ids_set = set()
        display_subjects_qs = Subject.objects.none()
        has_composite = False
        if grading_required.is_advance:
            composite = CompositeSubject.objects.filter(user=request.user).first()
            if composite:
                component_ids_set = set(composite.subjects.values_list('id', flat=True))
                has_composite = True
                if composite.allow_to_use:
                    display_subjects_qs = Subject.objects.filter(
                        id__in=required_subject_ids, user=request.user
                    ).exclude(id__in=component_ids_set).order_by('nameSubject')
                else:
                    display_subjects_qs = Subject.objects.filter(
                        id__in=required_subject_ids, user=request.user
                    ).order_by('nameSubject')

        if not has_composite:
            display_subjects_qs = Subject.objects.filter(
                id__in=required_subject_ids, user=request.user
            ).order_by('nameSubject')

        # Get subordinate users
        subordinate_user_ids = Teacher.objects.filter(created_by=request.user).values_list('user_id', flat=True)
        all_user_ids = list(subordinate_user_ids) + [request.user.id]

        # Grade setup
        if grading_required.is_primary:
            grade_thresholds = {
                'A': grading_required.grade_a, 'B': grading_required.grade_b, 'C': grading_required.grade_c,
                'D': grading_required.grade_d, 'E': grading_required.grade_f
            }
        elif grading_required.is_advance:
            grade_thresholds = {
                'A': grading_required.grade_a, 'B': grading_required.grade_b, 'C': grading_required.grade_c,
                'D': grading_required.grade_d, 'E': grading_required.grade_e, 'S': grading_required.grade_s,
                'F': grading_required.grade_f
            }
        else:  # O-level
            grade_thresholds = {
                'A': grading_required.grade_a, 'B': grading_required.grade_b, 'C': grading_required.grade_c,
                'D': grading_required.grade_d, 'F': grading_required.grade_f
            }
        
        sorted_grades = sorted(grade_thresholds.items(), key=lambda item: item[1], reverse=True)
        grade_list = [grade[0] for grade in sorted_grades] + ['-']

        # Get all students and prefetch marks
        students = Student.objects.filter(teacherclass__in=selected_classes).prefetch_related(
            Prefetch(
                'marks',
                queryset=Mark.objects.filter(
                    user_id__in=all_user_ids,
                    examinationname=examination,
                    subject__id__in=required_subject_ids
                ).select_related('subject'),
                to_attr='prefetched_marks'
            )
        )

        if not students.exists():
            messages.warning(request, f"No students found for the selected classes.")
            context.update({
                'selected_classes': selected_classes,
                'selected_examination': examination,
                'selected_class_ids_list': selected_class_ids_list
            })
            return render(request, 'subject_grade_distribution.html', context)

        # Calculate grade distribution
        subject_grade_counts = []
        summary_counts = {grade: 0 for grade in grade_list[:-1]}  # Exclude '-'
        total_distinct_students = 0
        processed_students = set()

        # First, process regular display subjects
        for subject in display_subjects_qs:
            grade_counts = {'subject': subject.nameSubject or "Unnamed Subject", 'total_students': 0}
            for grade in grade_list:
                grade_counts[grade] = 0
            counts = defaultdict(int)
            total = 0
            for student in students:
                mark = None
                for m in student.prefetched_marks:
                    if m.subject_id == subject.id:
                        mark = m.marks
                        break
                if mark is not None:
                    total += 1
                    g = get_grade(mark, {v: k for k, v in grade_thresholds.items()})
                    counts[g] += 1
                    summary_counts[g] += 1
                    processed_students.add(student.id)
            grade_counts['total_students'] = total
            for g in grade_list[:-1]:
                grade_counts[g] = counts[g]
            grade_counts['-'] = 0
            subject_grade_counts.append(grade_counts)

        # Handle composite if applicable
        if has_composite and composite:
            comp_counts = {'subject': composite.subject_name or "Composite Subject", 'total_students': 0}
            comp_summary_add = defaultdict(int)
            for grade in grade_list:
                comp_counts[grade] = 0
            counts = defaultdict(int)
            total = 0
            for student in students:
                comp_marks = [m.marks for m in student.prefetched_marks if m.subject_id in component_ids_set]
                valid_comp_marks = [m for m in comp_marks if m is not None and not pd.isna(m)]
                if valid_comp_marks:
                    avg_mark = round(sum(valid_comp_marks) / len(valid_comp_marks), 2)
                    total += 1
                    g = get_grade(avg_mark, {v: k for k, v in grade_thresholds.items()})
                    counts[g] += 1
                    comp_summary_add[g] += 1
            comp_counts['total_students'] = total
            for g in grade_list[:-1]:
                comp_counts[g] = counts[g]
                summary_counts[g] += comp_summary_add[g]
            comp_counts['-'] = 0
            subject_grade_counts.append(comp_counts)

        total_distinct_students = len(processed_students)

        summary_grade_counts = {'subject': f'Summary for Selected Classes', 'total_students': total_distinct_students}
        for grade in grade_list:
            summary_grade_counts[grade] = summary_counts[grade] if grade != '-' else 0

        # Store selections in session for PDF download
        selected_class_ids = ','.join(str(cid) for cid in class_ids)
        request.session['selected_class_ids'] = selected_class_ids
        request.session['selected_grade_id'] = grade_id
        request.session['selected_examination_id'] = examination_id

        # Prepare final context
        context.update({
            'subject_grade_counts': subject_grade_counts,
            'summary_grade_counts': summary_grade_counts,
            'grade_list': grade_list,
            'grading_system': grading_required,
            'selected_classes': selected_classes,
            'selected_examination': examination,
            'level': level,
            'selected_class_ids': selected_class_ids,
            'selected_class_ids_list': selected_class_ids_list
        })

        return render(request, 'subject_grade_distribution.html', context)

    return render(request, 'subject_grade_distribution.html', context)

@login_required
def top_ten_subjects(request):
    logger = logging.getLogger(__name__)

    def determine_grade(mark, grading):
        if grading.is_primary:
            if mark >= grading.grade_a: return 'A'
            elif mark >= grading.grade_b: return 'B'
            elif mark >= grading.grade_c: return 'C'
            elif mark >= grading.grade_d: return 'D'
            else: return 'E'
        elif grading.is_advance:
            if mark >= grading.grade_a: return 'A'
            elif mark >= grading.grade_b: return 'B'
            elif mark >= grading.grade_c: return 'C'
            elif mark >= grading.grade_d: return 'D'
            elif mark >= grading.grade_e: return 'E'
            elif mark >= grading.grade_s: return 'S'
            else: return 'F'
        else:  # O-Level
            if mark >= grading.grade_a: return 'A'
            elif mark >= grading.grade_b: return 'B'
            elif mark >= grading.grade_c: return 'C'
            elif mark >= grading.grade_d: return 'D'
            else: return 'F'

    # Fetch data for the selection form
    grades_display = GradingModel.objects.filter(user=request.user)
    examinations_display = ExaminationName.objects.filter(user=request.user)
    classes_display = TeacherClass.objects.filter(
        user=request.user, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')  # Fetch classes

    context = {
        'grades': grades_display,
        'examinations': examinations_display,
        'classes': classes_display,  # Add classes to context
    }

    if request.method == 'POST':
        grade_id = request.POST.get('grade_id')
        examination_id = request.POST.get('examination_id')
        class_ids = request.POST.getlist('class_id')  # Get list of selected class IDs

        # --- Form Validation ---
        if not grade_id or not examination_id or not class_ids:
            context['error_message'] = "Please select a grading system, an examination, and at least one class."
            return render(request, 'gpa_options.html', context)

        # Fetch selected objects
        grading_required = get_object_or_404(GradingModel, id=grade_id, user=request.user)
        examination_required = get_object_or_404(ExaminationName, id=examination_id, user=request.user)
        selected_classes = TeacherClass.objects.filter(
            id__in=class_ids, 
            user=request.user, 
            academicclassyear__active_year=True
        ).select_related('ClassName', 'academicclassyear')

        if not selected_classes.exists():
            context['error_message'] = "No valid classes selected."
            return render(request, 'gpa_options.html', context)

        level = 'Primary' if grading_required.is_primary else 'Alevel' if grading_required.is_advance else 'Olevel'
        
        if not grading_required.is_primary:
            grade_points = {'A': 1.0, 'B': 2.0, 'C': 3.0, 'D': 4.0, **({'E': 5.0, 'S': 6.0, 'F': 7.0} if grading_required.is_advance else {'F': 5.0})}
        else:
            grade_points = {}

        subordinate_teachers = Teacher.objects.filter(created_by=request.user).values_list('user_id', flat=True)
        all_teacher_user_ids = list(subordinate_teachers) + [request.user.id]

        # Get all required subjects first
        all_required_subjects = RequiredSubject.objects.filter(
            user=request.user, 
            level=level, 
            teacherclass__in=selected_classes
        )
        all_subject_ids = all_required_subjects.values_list('subject_id', flat=True).distinct()
        all_subjects = Subject.objects.filter(
            id__in=all_subject_ids, 
            user=request.user
        ).order_by('nameSubject')

        # Handle CompositeSubject for A-Level
        composite = None
        component_ids_set = set()
        display_subjects_qs = all_subjects
        if grading_required.is_advance:
            composite = CompositeSubject.objects.filter(user=request.user).first()
            if composite:
                component_ids_set = set(composite.subjects.values_list('id', flat=True))
                if composite.allow_to_use:
                    display_subjects_qs = all_subjects.exclude(id__in=component_ids_set)
                else:
                    display_subjects_qs = all_subjects

        # Get students and prefetch ALL marks (including components)
        students = Student.objects.filter(teacherclass__in=selected_classes).prefetch_related(
            Prefetch(
                'marks',
                queryset=Mark.objects.filter(
                    user_id__in=all_teacher_user_ids,
                    teacherclass__in=selected_classes,
                    examinationname=examination_required,
                    subject__id__in=all_subject_ids
                ).select_related('subject'),
                to_attr='prefetched_marks'
            )
        )

        subjects_data = []
        
        # Process regular display subjects
        for subject in display_subjects_qs:
            total_score = 0.0
            student_count = 0
            for student in students:
                mark = None
                for m in student.prefetched_marks:
                    if m.subject_id == subject.id:
                        mark = m.marks
                        break
                if mark is not None and not pd.isna(mark):
                    student_count += 1
                    if grading_required.is_primary:
                        total_score += mark
                    else:
                        total_score += grade_points.get(determine_grade(mark, grading_required), 0)
            if student_count > 0:
                performance_score = round(total_score / student_count, 2)
                subjects_data.append({
                    'subject_name': subject.nameSubject or "Unnamed Subject",
                    'performance_score': performance_score,
                })

        # Handle composite only if allow_to_use=True
        if grading_required.is_advance and composite and composite.allow_to_use:
            total_score = 0.0
            student_count = 0
            for student in students:
                comp_marks = [m.marks for m in student.prefetched_marks if m.subject_id in component_ids_set]
                valid_comp_marks = [m for m in comp_marks if m is not None and not pd.isna(m)]
                if valid_comp_marks:
                    student_count += 1
                    avg_mark = round(sum(valid_comp_marks) / len(valid_comp_marks), 2)
                    total_score += grade_points.get(determine_grade(avg_mark, grading_required), 0)
            if student_count > 0:
                performance_score = round(total_score / student_count, 2)
                subjects_data.append({
                    'subject_name': composite.subject_name or "Composite Subject",
                    'performance_score': performance_score,
                })

        if grading_required.is_primary:
            sorted_subjects = sorted(subjects_data, key=lambda x: x['performance_score'], reverse=True)[:10]
        else:
            sorted_subjects = sorted(subjects_data, key=lambda x: x['performance_score'])[:10]
        
        class_subjects_data = [{
            'classes': selected_classes,
            'subjects': sorted_subjects
        }]

        performance_label = 'Average Mark' if grading_required.is_primary else 'GPA'

        return render(request, 'top_ten_subjects.html', {
            'class_subjects_data': class_subjects_data,
            'grading_system': grading_required,
            'examination': examination_required,
            'level': level,
            'performance_label': performance_label
        })

    return render(request, 'gpa_options.html', context)

@login_required
def download_division_summary_pdf(request, class_ids, grade_id, examination_id):
    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")
    
    class_id_list = [cid.strip() for cid in class_ids.split(',') if cid.strip()]  # Fixed: Strip whitespace and filter empties
    selected_classes = TeacherClass.objects.filter(
        id__in=class_id_list, 
        user=request.user, 
        academicclassyear__active_year=True
    ).select_related('ClassName', 'academicclassyear')
    
    if not selected_classes.exists():
        raise Http404("No valid classes selected.")
    
    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    examination_name = get_object_or_404(ExaminationName, id=examination_id, user=request.user)
    display = DisplayModel.objects.filter(user=request.user).first()
    
    level = 'Alevel' if grading.is_advance else 'Olevel' if not grading.is_primary else 'Primary'
    required_subjects = RequiredSubject.objects.filter(user=request.user, level=level, teacherclass__in=selected_classes)
    subject_ids = required_subjects.values_list('subject_id', flat=True).distinct()
    subjects = Subject.objects.filter(id__in=subject_ids, user=request.user).order_by('nameSubject')
    
    # Handle CompositeSubject for A-Level
    composite = None
    component_ids_set = set()
    display_subjects_qs = subjects
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects_qs = subjects.exclude(id__in=component_ids_set)
            else:
                display_subjects_qs = subjects
    
    mark_filter = Q(subject__in=subjects, examinationname=examination_name)
    students = Student.objects.filter(teacherclass__in=selected_classes).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(mark_filter).select_related('subject', 'examinationname', 'user'))
    )
    
    # Define grade thresholds and points
    if grading.is_primary:
        exclude_subjects = set()
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'E'
        }
        grade_points = {}  # Not used for primary
    elif grading.is_advance:
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
    else:  # O-level
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
    
    if not grading.is_primary:
        division_thresholds = [
            {'max': grading.division_1, 'label': 'I'},
            {'max': grading.division_2, 'label': 'II'},
            {'max': grading.division_3, 'label': 'III'},
            {'max': grading.division_4, 'label': 'IV'},
            {'max': float('inf'), 'label': '0'}
        ]
    else:
        division_thresholds = []
    
    def get_division(grades_for_division):
        if grading.is_primary:
            return None, None
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        req_subs = 3 if grading.is_advance else 7
        if num_valid_subjects < req_subs:
            return "Inc", 0
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs]
        total_points = sum(grade_points[g] for g in sorted_grades)
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                return threshold['label'], total_points
        return 'IV', total_points
    
    # Calculate data based on grading type
    if grading.is_primary:
        # For primary: Average marks per subject across all classes
        subject_averages = {}
        for subject in display_subjects_qs:
            all_marks_in_subject = []
            for student in students:
                mark_obj = student.marks.filter(subject=subject, examinationname=examination_name).first()
                if mark_obj:
                    all_marks_in_subject.append(mark_obj.marks)
            valid_marks = [m for m in all_marks_in_subject if m is not None and not pd.isna(m)]
            avg = sum(valid_marks) / len(valid_marks) if valid_marks else 0
            subject_averages[subject.nameSubject or 'Unnamed'] = round(avg, 2)
        
        summary_data = subject_averages
        summary_type = 'subject_averages'
        table_title = "Subject Average Marks"
        table_headers = ['Subject', 'Average Mark']
        table_rows = [[sub, str(avg)] for sub, avg in summary_data.items()]
        table_rows.append(['Total Subjects', str(len(summary_data))])
    else:
        # For non-primary: Division counts across all classes
        division_counts = {'I': 0, 'II': 0, 'III': 0, 'IV': 0, 'Inc': 0, '0': 0}
        for student in students:
            student_marks_dict = {m.subject_id: m.marks for m in student.marks.all()}
            grades_for_division = []
            for subject in display_subjects_qs:
                skip_subject = False
                if (composite and not composite.allow_to_use and subject.id in component_ids_set):
                    skip_subject = True
                if not skip_subject:
                    mark_value = student_marks_dict.get(subject.id)
                    grade = get_grade(mark_value, grade_thresholds, is_primary=grading.is_primary)
                    if subject.id not in exclude_subjects:
                        grades_for_division.append(grade)
            
            # Handle composite for division
            if composite:
                component_marks = [student_marks_dict.get(sid) for sid in component_ids_set]
                valid_comp_marks = [m for m in component_marks if m is not None and not pd.isna(m)]
                if valid_comp_marks:
                    avg_mark = round(sum(valid_comp_marks) / len(valid_comp_marks), 2)
                    comp_grade = get_grade(avg_mark, grade_thresholds, is_primary=grading.is_primary)
                    grades_for_division.append(comp_grade)
            
            division, _ = get_division(grades_for_division)
            division_counts[division] += 1
        
        total_students = sum(division_counts.values())
        division_counts['subject'] = 'Total'
        division_counts['total_students'] = total_students
        
        summary_data = division_counts
        summary_type = 'division_counts'
        table_title = "Division Distribution"
        table_headers = ['Division', 'Number of Students']
        division_list = ['I', 'II', 'III', 'IV', 'Inc', '0']
        table_rows = [[div, str(division_counts[div])] for div in division_list]
        table_rows.append(['Total', str(total_students)])
    
    class_names = ', '.join([c.ClassName.class_name or 'Unnamed Class' for c in selected_classes])
    
    # Prepare PDF
    response = HttpResponse(content_type='application/pdf')
    exam_suffix = f"_{examination_name.exam_name.replace(' ', '_')}"
    filename = f"division_summary_{class_names.replace(' ', '_')}{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []
    
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=8, leading=9, alignment=TA_LEFT)
    header_style.alignment = subheader_style.alignment = body_style.alignment = TA_CENTER
    
    # Header
    header_text = display.header if display else f"{table_title} for {class_names} - {examination_name.exam_name}"
    elements.append(Paragraph(header_text, header_style))
    elements.append(Spacer(1, 4))
    elements.append(Paragraph(f"Academic Year: {datetime.now().year}", subheader_style))
    elements.append(Spacer(1, 8))
    
    # Summary Table
    table_data = [table_headers] + table_rows
    
    available_width = A4[0] - 30
    col_widths = [available_width * 0.5, available_width * 0.5]
    
    table = Table(table_data, colWidths=col_widths, repeatRows=1)
    table.setStyle(TableStyle([
        ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
        ('BACKGROUND', (0, 0), (-1, 0), colors.lightgrey),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('FONTSIZE', (0, 0), (-1, -1), 8),
        ('LEADING', (0, 0), (-1, -1), 9),
        ('BOX', (0, 0), (-1, -1), 1, colors.black),
        ('LEFTPADDING', (0, 0), (-1, -1), 4),
        ('RIGHTPADDING', (0, 0), (-1, -1), 4),
        ('TOPPADDING', (0, 0), (-1, -1), 4),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ('BACKGROUND', (0, -1), (-1, -1), colors.HexColor('#f1f3f5')),
    ]))
    
    elements.append(table)
    elements.append(Spacer(1, 10))
    elements.append(Paragraph(f"Generated on: {current_time}", body_style))
    
    try:
        doc.build(elements)
        logger.debug(f"Memory usage after PDF generation: {process.memory_info().rss / 1024 / 1024:.2f} MB")
        messages.success(request, 'Division summary PDF generated successfully!')
        return response
    except Exception as e:
        logger.error(f"Error generating PDF: {str(e)}")
        messages.error(request, f"Error generating PDF: {str(e)}")
        return redirect('division_summary')

@login_required
def download_grade_distribution_pdf(request, class_ids, grade_id, examination_id):
    # Parse class_ids string into list of integers
    try:
        class_ids_list = [int(cid.strip()) for cid in class_ids.split(',')]
    except ValueError:
        raise Http404("Invalid class IDs provided.")

    # Fetch required objects
    teacherclasses = TeacherClass.objects.filter(
        id__in=class_ids_list,
        user=request.user,
        academicclassyear__active_year=True
    )
    if not teacherclasses.exists():
        raise Http404("No active teacher classes found for the selected IDs.")

    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    examination = get_object_or_404(ExaminationName, id=examination_id, user=request.user)

    # Determine level and fetch subjects (unique across all selected classes)
    level = 'Primary' if grading.is_primary else 'Alevel' if grading.is_advance else 'Olevel'
    required_subjects = RequiredSubject.objects.filter(
        user=request.user,
        level=level,
        teacherclass__in=teacherclasses
    ).values_list('subject_id', flat=True).distinct()
    subjects = Subject.objects.filter(
        id__in=required_subjects,
        user=request.user
    ).order_by('nameSubject')

    # Handle CompositeSubject for A-Level
    composite = None
    component_ids_set = set()
    display_subjects_qs = subjects
    has_composite = False
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            has_composite = True
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects_qs = subjects.exclude(id__in=component_ids_set)
            else:
                display_subjects_qs = subjects

    # Define grade thresholds and get all possible grades
    if grading.is_primary:
        thresholds = [
            (grading.grade_a, 'A'),
            (grading.grade_b, 'B'),
            (grading.grade_c, 'C'),
            (grading.grade_d, 'D'),
            (0, 'E')
        ]
    elif grading.is_advance:
        thresholds = [
            (grading.grade_a, 'A'),
            (grading.grade_b, 'B'),
            (grading.grade_c, 'C'),
            (grading.grade_d, 'D'),
            (grading.grade_e, 'E'),
            (grading.grade_s, 'S'),
            (0, 'F')
        ]
    else:  # O-Level
        thresholds = [
            (grading.grade_a, 'A'),
            (grading.grade_b, 'B'),
            (grading.grade_c, 'C'),
            (grading.grade_d, 'D'),
            (0, 'F')
        ]

    all_grades = [grade for _, grade in thresholds]
    grade_thresholds_dict = {v: k for k, v in thresholds}

    def get_grade(mark):
        for threshold, grade in sorted(thresholds, reverse=True):
            if mark >= threshold:
                return grade
        return thresholds[-1][1]

    # Get students and prefetch marks
    students = Student.objects.filter(teacherclass__in=teacherclasses).prefetch_related(
        Prefetch(
            'marks',
            queryset=Mark.objects.filter(
                teacherclass__in=teacherclasses,
                examinationname=examination,
                subject__id__in=required_subjects
            ).select_related('subject'),
            to_attr='prefetched_marks'
        )
    )

    # Aggregate grade distribution per subject (across all selected classes)
    grade_distribution = {}
    for subject in display_subjects_qs:
        distribution = {grade: 0 for grade in all_grades}
        total_students = 0
        for student in students:
            mark = None
            for m in student.prefetched_marks:
                if m.subject_id == subject.id:
                    mark = m.marks
                    break
            if mark is not None:
                total_students += 1
                grade = get_grade(mark)
                distribution[grade] += 1
        if total_students > 0:
            percentages = {grade: round((count / total_students * 100), 1) for grade, count in distribution.items()}
            grade_distribution[subject.nameSubject] = {
                'counts': distribution,
                'total': total_students,
                'percentages': percentages
            }

    # Handle composite if applicable
    if has_composite and composite:
        comp_distribution = {grade: 0 for grade in all_grades}
        total_students = 0
        for student in students:
            comp_marks = [m.marks for m in student.prefetched_marks if m.subject_id in component_ids_set]
            valid_comp_marks = [m for m in comp_marks if m is not None]
            if valid_comp_marks:
                total_students += 1
                avg_mark = round(sum(valid_comp_marks) / len(valid_comp_marks), 2)
                grade = get_grade(avg_mark)
                comp_distribution[grade] += 1
        if total_students > 0:
            percentages = {grade: round((count / total_students * 100), 1) for grade, count in comp_distribution.items()}
            grade_distribution[composite.subject_name] = {
                'counts': comp_distribution,
                'total': total_students,
                'percentages': percentages
            }

    # Create PDF response
    response = HttpResponse(content_type='application/pdf')
    class_names = ', '.join([tc.ClassName.class_name for tc in teacherclasses])
    filename = f"grade_distribution_{class_names.replace(' ', '_')}_{examination.exam_name}.pdf".replace(',', '_')
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=30, leftMargin=30, topMargin=40, bottomMargin=30)
    elements = []
    styles = getSampleStyleSheet()

    # Customize styles for better readability
    title_style = ParagraphStyle(
        'CustomTitle',
        parent=styles['Title'],
        fontSize=16,
        spaceAfter=30,
        alignment=TA_CENTER
    )
    heading2_style = ParagraphStyle(
        'CustomHeading2',
        parent=styles['Heading2'],
        fontSize=12,
        spaceAfter=12,
        alignment=TA_CENTER
    )
    heading3_style = ParagraphStyle(
        'CustomHeading3',
        parent=styles['Heading3'],
        fontSize=11,
        spaceAfter=8,
        alignment=TA_LEFT
    )
    normal_style = ParagraphStyle(
        'CustomNormal',
        parent=styles['Normal'],
        fontSize=10,
        spaceAfter=6
    )

    # Title
    elements.append(Paragraph("Grade Distribution Report", title_style))
    elements.append(Spacer(1, 12))
    elements.append(Paragraph(f"Classes: {class_names}", heading2_style))
    elements.append(Paragraph(f"Examination: {examination.exam_name or 'Unnamed Exam'}", heading2_style))
    elements.append(Paragraph(f"Level: {level}", normal_style))
    elements.append(Spacer(1, 20))

    # Summary table for all subjects
    if grade_distribution:
        # Overall summary
        elements.append(Paragraph("Overall Summary", heading2_style))
        elements.append(Spacer(1, 8))

        summary_data = [['Subject', 'Total Students', 'A (%)', 'B (%)', 'C (%)', 'D (%)', 'E/F/S (%)']]
        for subject_name, data in grade_distribution.items():
            high_grades = data['percentages'].get('A', 0) + data['percentages'].get('B', 0)
            mid_grades = data['percentages'].get('C', 0) + data['percentages'].get('D', 0)
            low_grades = sum(data['percentages'].get(g, 0) for g in all_grades if g not in ['A', 'B', 'C', 'D'])
            summary_data.append([
                subject_name[:20],  # Truncate long names
                str(data['total']),
                f"{high_grades:.1f}%",
                f"{mid_grades:.1f}%",
                f"{data['percentages'].get('C', 0):.1f}%",
                f"{data['percentages'].get('D', 0):.1f}%",
                f"{low_grades:.1f}%"
            ])

        summary_table = Table(summary_data, colWidths=[100, 60, 50, 50, 50, 50, 60])
        summary_table.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.darkblue),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.whitesmoke),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, -1), 9),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.lightgrey]),
        ]))
        elements.append(summary_table)
        elements.append(Spacer(1, 20))

        # Detailed distribution per subject
        elements.append(Paragraph("Detailed Distribution per Subject", heading2_style))
        elements.append(Spacer(1, 8))

        for subject_name, data in grade_distribution.items():
            elements.append(Paragraph(f"Subject: {subject_name}", heading3_style))
            elements.append(Spacer(1, 6))

            # Table for counts
            count_data = [['Grade', 'Count', 'Percentage']]
            for grade in all_grades:
                count = data['counts'][grade]
                perc = data['percentages'][grade]
                count_data.append([grade, str(count), f"{perc:.1f}%"])

            count_table = Table(count_data, colWidths=[60, 80, 80])
            count_table.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), colors.lightblue),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.black),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, -1), 8),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#f0f8ff')]),
            ]))
            elements.append(count_table)
            elements.append(Spacer(1, 12))
    else:
        elements.append(Paragraph("No grade distribution data available for the selected criteria.", normal_style))
        elements.append(Spacer(1, 12))

    # Footer
    elements.append(Spacer(1, 20))
    elements.append(Paragraph(f"Generated on: {datetime.now().strftime('%Y-%m-%d %H:%M')}", normal_style))

    doc.build(elements)
    return response


from django.shortcuts import render, redirect, get_object_or_404
from django.contrib.auth.decorators import login_required
from django.contrib import messages
from django.conf import settings
from django.urls import reverse
from django.http import HttpResponse
from django.views.decorators.csrf import csrf_exempt  # For callback if needed
from django.db.models import Prefetch  # For efficient querying
from decimal import Decimal
import uuid
import logging
import json  # For potential JSON parsing in callback
from .models import Payment, PaymentNotification
from snippe_payment import SnippePaymentClient

logger = logging.getLogger(__name__)


def _extract_snippe_payload(response):
    payload = response.get("data") if isinstance(response, dict) else {}
    if not isinstance(payload, dict):
        return {}
    nested = payload.get("data")
    if isinstance(nested, dict):
        return nested
    return payload


def _map_snippe_payment_status(status_value):
    status_value = str(status_value or "").strip().lower()
    if status_value in {"completed", "success", "paid"}:
        return "SUCCESS"
    if status_value in {"failed", "error", "declined"}:
        return "FAILED"
    return "PENDING"


@login_required
def payment_form(request):
    """
    View to display payment form and handle payment initiation.
    """
    if request.method == 'POST':
        # Extract form data
        customer_name = request.POST.get('customer_name', request.user.get_full_name() or request.user.username)
        customer_email = request.POST.get('customer_email', request.user.email)
        customer_phone = request.POST.get('customer_phone')
        amount_str = request.POST.get('amount')
        payment_method = request.POST.get('payment_method', 'PHONE')  # Default to phone push

        try:
            amount = Decimal(amount_str)
            if amount <= 0:
                raise ValueError("Amount must be positive.")
        except ValueError as e:
            messages.error(request, f"Invalid amount: {e}")
            return render(request, 'payments/payment_form.html')

        # Generate unique order_id and transaction_id
        order_id = str(uuid.uuid4())[:32]  # Truncate if needed for max_length
        transaction_id = str(uuid.uuid4())[:32]

        # Create Payment instance (initially PENDING)
        payment = Payment.objects.create(
            user=request.user,
            amount=amount,
            order_id=order_id,
            transaction_id=transaction_id,
            payment_method=payment_method,
            status='PENDING'
        )

        # Create initial PENDING notification
        PaymentNotification.objects.create(
            user=request.user,
            order_id=order_id,
            amount=amount,
            status='PENDING',
            success_payment=False,
            payment=payment,
            created_at=payment.created_at
        )

        # Callback URL for Snippe
        callback_url = request.build_absolute_uri(reverse('snippe_callback'))
        client = SnippePaymentClient()

        try:
            if payment_method == 'PHONE':
                response = client.create_mobile_payment(
                    amount=int(amount),
                    phone_number=customer_phone,
                    first_name=customer_name.split(" ")[0] if customer_name else "",
                    last_name=" ".join(customer_name.split(" ")[1:]) if customer_name else "",
                    email=customer_email,
                    order_id=order_id,
                    currency="TZS",
                    webhook_url=callback_url,
                    idempotency_key=order_id,
                )
            else:
                response = client.create_dynamic_qr_payment(
                    amount=int(amount),
                    phone_number=customer_phone or "",
                    first_name=customer_name.split(" ")[0] if customer_name else "",
                    last_name=" ".join(customer_name.split(" ")[1:]) if customer_name else "",
                    email=customer_email,
                    order_id=order_id,
                    currency="TZS",
                    webhook_url=callback_url,
                    idempotency_key=order_id,
                )
            logger.info(f"Snippe payment response: {response}")
        except Exception as e:
            logger.error(f"Snippe API error: {e}")
            payment.status = 'FAILED'
            payment.save()
            # Update notification to FAILED
            notification = PaymentNotification.objects.filter(order_id=order_id, user=request.user).first()
            if notification:
                notification.status = 'FAILED'
                notification.success_payment = False
                notification.save()
            messages.error(request, "Failed to connect to payment gateway.")
            return redirect('payment_form')

        if not response.get("success"):
            payment.status = 'FAILED'
            payment.save()
            notification = PaymentNotification.objects.filter(order_id=order_id, user=request.user).first()
            if notification:
                notification.status = 'FAILED'
                notification.success_payment = False
                notification.save()
            error_msg = response.get("error") or response.get("data") or "Payment request failed."
            messages.error(request, f"Payment request failed: {error_msg}")
            return redirect('payment_form')

        snippe_data = _extract_snippe_payload(response)
        payment.status = _map_snippe_payment_status(snippe_data.get("status"))
        payment.callback_data = snippe_data
        payment.save()

        if payment_method == 'PHONE':
            messages.success(request, "Payment request sent to your phone!")
            return redirect('payment_success', transaction_id=transaction_id)

        payment_url = snippe_data.get("payment_url")
        if payment_url:
            return redirect(payment_url)
        messages.info(request, "Payment link ready! Check your email or contact support if needed.")

        return redirect('payment_form')

    return render(request, 'payments/payment_form.html')

@login_required
def payment_success(request, transaction_id):
    """
    View for payment success page, fetches latest status.
    """
    payment = get_object_or_404(Payment, transaction_id=transaction_id, user=request.user)
    context = {'payment': payment}
    return render(request, 'payments/payment_success.html', context)

@csrf_exempt  # Snippe callbacks may not include CSRF
def snippe_callback(request):
    """
    Callback view from Snippe to update payment status and create/update notification.
    Expects POST data from Snippe.
    """
    if request.method == 'POST':
        # Parse callback data (handle form or JSON)
        if 'application/json' in request.content_type:
            callback_data = json.loads(request.body or "{}")
        else:
            callback_data = dict(request.POST)

        payload = callback_data.get("data") if isinstance(callback_data, dict) else {}
        metadata = payload.get("metadata") if isinstance(payload, dict) else {}
        order_id = metadata.get("order_id") if isinstance(metadata, dict) else None
        status = _map_snippe_payment_status(payload.get('status'))
        amount_str = (payload.get("amount") or {}).get("value") if isinstance(payload.get("amount"), dict) else 0

        try:
            amount = Decimal(amount_str) if amount_str else Decimal(0)
        except (ValueError, TypeError):
            amount = Decimal(0)

        try:
            payment = Payment.objects.get(order_id=order_id)
            # Preserve existing callback_data and merge new
            existing_data = payment.callback_data or {}
            existing_data.update(callback_data if isinstance(callback_data, dict) else {})
            payment.callback_data = existing_data
            
            payment.status = status
            payment.save()

            # Always get or create notification, then update status/success
            notification, created = PaymentNotification.objects.get_or_create(
                user=payment.user,
                order_id=order_id,
                defaults={
                    'amount': amount,
                    'status': payment.status,
                    'success_payment': (payment.status == 'SUCCESS'),
                    'payment': payment,
                    'created_at': payment.created_at
                }
            )
            # Update status if already existed (e.g., from PENDING to SUCCESS)
            notification.status = payment.status
            notification.success_payment = (payment.status == 'SUCCESS')
            notification.amount = amount  # Ensure amount is current
            notification.save()

            logger.info(
                "Snippe callback processed: order_id=%s, status=%s, notification_created=%s",
                order_id,
                payment.status,
                created,
            )
            # Respond to Snippe (success acknowledgment)
            return HttpResponse('OK', content_type='text/plain')
        except Payment.DoesNotExist:
            logger.error("Snippe callback: Payment not found for order_id=%s", order_id)
            pass

    return HttpResponse('Invalid request', status=400)

@login_required
def notifications_list(request):
    """
    View to render user's payment notifications (added via admin or callbacks).
    """
    notifications = PaymentNotification.objects.filter(
        user=request.user
    ).prefetch_related(
        Prefetch('payment', queryset=Payment.objects.select_related('user'))
    ).order_by('-created_at')
    context = {'notifications': notifications}
    return render(request, 'payments/notifications.html', context)


    # views.py (add this new view, learning from download_pdf)
from django.shortcuts import get_object_or_404, redirect
from django.contrib import messages
from django.http import HttpResponse
from django.contrib.auth.decorators import login_required
import logging
import psutil
from datetime import datetime
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER, TA_LEFT
from reportlab.lib.units import cm
from reportlab.platypus import Image as RLImage
from PIL import Image as PILImage
import os
import pandas as pd  # Assuming pd.isna is used
from django.db.models import Q, Sum, Avg
from django.db.models import Prefetch

logger = logging.getLogger(__name__)
@login_required
def download_merged_pdf(request):
    if request.method != 'POST':
        messages.error(request, "Invalid request method.")
        return redirect('generate_reports')  # Assuming the template URL name

    class_ids = request.POST.getlist('class_ids')
    grade_id = request.POST.get('grade_id')
    examination_name_id = request.POST.get('examination_id')

    if not class_ids or not grade_id or not examination_name_id:
        messages.error(request, "Class(es), grading system, and examination are required.")
        return redirect('generate_reports')

    # Fetch multiple teacherclasses
    teacherclasses = TeacherClass.objects.filter(
        id__in=class_ids, user=request.user, academicclassyear__active_year=True
    )
    if not teacherclasses.exists():
        messages.error(request, "No valid classes found.")
        return redirect('generate_reports')

    grading = get_object_or_404(GradingModel, id=grade_id, user=request.user)
    examination_name = get_object_or_404(ExaminationName, id=examination_name_id, user=request.user)

    if grading.is_primary:
        level = 'Primary'
    elif grading.is_advance:
        level = 'Alevel'
    else:
        level = 'Olevel'

    # Get required subjects for the level (assuming same across classes; use first class's context)
    required_subjects = RequiredSubject.objects.filter(
        user=request.user, level=level, teacherclass__in=teacherclasses
    ).values_list('subject_id', flat=True).distinct()
    subjects = Subject.objects.filter(id__in=required_subjects, user=request.user).order_by('nameSubject')

    # CompositeSubject integration for A-level
    subjects_list = []
    display_subjects_qs = subjects
    composite = None
    component_ids_set = set()
    if grading.is_advance:
        composite = CompositeSubject.objects.filter(user=request.user).first()
        if composite:
            component_ids_set = set(composite.subjects.values_list('id', flat=True))
            if composite.allow_to_use:
                display_subjects_qs = subjects.exclude(id__in=component_ids_set)
                subjects_list = list(display_subjects_qs.values('id', 'nameSubject'))
                subjects_list.append({'id': 'composite', 'nameSubject': composite.subject_name})
            else:
                display_subjects_qs = subjects
                subjects_list = list(display_subjects_qs.values('id', 'nameSubject'))
        else:
            subjects_list = list(subjects.values('id', 'nameSubject'))
    else:
        subjects_list = list(subjects.values('id', 'nameSubject'))

    mark_filter = Q(subject__in=subjects, examinationname=examination_name)

    # Fetch all students across selected classes
    students = Student.objects.filter(teacherclass__in=teacherclasses).prefetch_related(
        Prefetch('marks', queryset=Mark.objects.filter(mark_filter).select_related('subject', 'examinationname', 'user'))
    )

    all_marks = Mark.objects.filter(
        teacherclass__in=teacherclasses, subject__in=subjects, examinationname=examination_name
    ).select_related('user')
    teacher_map = {}
    for mark in all_marks:
        if mark.user_id:
            teacher = Teacher.objects.filter(user=mark.user).first()
            teacher_map[mark.user_id] = teacher.teacherName or mark.user.username if teacher else mark.user.username

    # Set exclude_subjects for O-level and A-level
    exclude_subjects = set()
    if not grading.is_primary:
        exclude_subjects = set(ExcludeSubject.objects.filter(user=request.user).values_list('exclude_subject_id', flat=True))

    # Set grade_thresholds and other configs (same as original)
    if grading.is_primary:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'E'
        }
        grade_points = {}  # Not used for primary
        min_subjects_for_division = None
        req_subs_for_div = None
    elif grading.is_advance:
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_e: 'E',
            grading.grade_s: 'S',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'E': 5, 'S': 6, 'F': 7, '-': 9}
        min_subjects_for_division = 3
        req_subs_for_div = 3
    else:  # O-level
        grade_thresholds = {
            grading.grade_a: 'A',
            grading.grade_b: 'B',
            grading.grade_c: 'C',
            grading.grade_d: 'D',
            grading.grade_f: 'F'
        }
        grade_points = {'A': 1, 'B': 2, 'C': 3, 'D': 4, 'F': 5, '-': 9}
        min_subjects_for_division = 7
        req_subs_for_div = 7

    division_thresholds = [
        {'max': grading.division_1, 'label': 'I'},
        {'max': grading.division_2, 'label': 'II'},
        {'max': grading.division_3, 'label': 'III'},
        {'max': grading.division_4, 'label': 'IV'},
        {'max': float('inf'), 'label': '0'}
    ]

    source_doc = SourceDocument.objects.filter(user=request.user, allow_to_be_used=True).first()
    remark_ranges = RemarkRange.objects.all()

    response = HttpResponse(content_type='application/pdf')
    class_names = ', '.join(tc.ClassName.class_name for tc in teacherclasses)
    exam_suffix = f"_{examination_name.exam_name.replace(' ', '_')}"
    filename = f"merged_student_report_{class_names.replace(' ', '_')}{exam_suffix}.pdf"
    response['Content-Disposition'] = f'attachment; filename="{filename}"'

    # Simplified document margins
    doc = SimpleDocTemplate(response, pagesize=A4, rightMargin=15, leftMargin=15, topMargin=20, bottomMargin=20)
    elements = []

    # Styling (same as original)
    styles = getSampleStyleSheet()
    header_style = styles['Heading1']
    subheader_style = styles['Heading2']
    body_style = styles['BodyText']
    footer_style = ParagraphStyle(name='Footer', parent=styles['BodyText'], fontSize=8, alignment=TA_CENTER, textColor=colors.grey)
    bold_style = ParagraphStyle(name='Bold', parent=styles['BodyText'], fontName='Helvetica-Bold', fontSize=9)
    small_style = ParagraphStyle(name='Small', parent=styles['Normal'], fontSize=5, alignment=TA_CENTER, leading=6)
    table_text_style = ParagraphStyle(name='TableText', parent=styles['Normal'], fontSize=6, leading=7, alignment=TA_LEFT, wordWrap='CJK')
    header_style.alignment = subheader_style.alignment = body_style.alignment = bold_style.alignment = TA_CENTER
    body_style.fontSize = 7

    def add_page_number(canvas, doc):
        page_num = canvas.getPageNumber()
        text = f"Page {page_num}"
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawCentredString(A4[0]/2, 15, text)
        canvas.restoreState()

    def get_grade(mark):
        if mark is None or pd.isna(mark):
            return '-'
        for threshold, grade in sorted(grade_thresholds.items(), reverse=True):
            if mark >= threshold:
                return grade
        return 'E' if grading.is_primary else 'F'

    def get_grade_color(grade):
        color_map = {
            'A': colors.HexColor('#28a745'),
            'B': colors.HexColor('#17a2b8'),
            'C': colors.HexColor('#3498db'),
            'D': colors.HexColor('#ffc107'),
            'E': colors.HexColor('#fd7e14'),
            'S': colors.HexColor('#6f42c1'),
            'F': colors.HexColor('#e74c3c'),
            '-': colors.HexColor('#495057')
        }
        return color_map.get(grade, colors.HexColor('#495057'))

    def get_remark(grade):
        remark_map = {
            'A': 'Excellent',
            'B': 'Very Good',
            'C': 'Good',
            'D': 'Pass',
            'F': 'Fail',
            '-': '-'
        }
        if grading.is_primary:
            remark_map['E'] = 'Fail'
        else:
            remark_map['E'] = 'Poor'
            remark_map['S'] = 'Subsidiary'
        return remark_map.get(grade, '-')

    def get_division(grades_for_division):
        if grading.is_primary:
            return "-", "-"
        filtered_grades = [g for g in grades_for_division if g != '-']
        num_valid_subjects = len(filtered_grades)
        if num_valid_subjects < req_subs_for_div:
            return "Inc", '-'
        sorted_grades = sorted(filtered_grades, key=lambda x: grade_points[x])[:req_subs_for_div]
        total_points = sum(grade_points[g] for g in sorted_grades)
        division = 'IV'
        for threshold in division_thresholds:
            if total_points <= threshold['max']:
                division = threshold['label']
                break
        return division, total_points

    # Load images (same as original)
    icon = None
    display = DisplayModel.objects.filter(user=request.user).first()
    if display and display.image:
        image_path = display.image.path
        logger.debug(f"Checking image file: {image_path}")
        if os.path.exists(image_path) and os.access(image_path, os.R_OK):
            try:
                with PILImage.open(image_path) as img:
                    img.verify()
                logger.debug(f"Image verified successfully: {image_path}")
                icon = RLImage(image_path, width=2*cm, height=2*cm)
                icon.hAlign = 'CENTER'
                logger.debug(f"Successfully loaded image: {image_path}")
            except Exception as e:
                logger.error(f"Error loading DisplayModel image: {str(e)}")

    sig_img = None
    stamp_img = None
    if source_doc:
        sig_path = source_doc.extracted_signature.path if source_doc.extracted_signature else None
        if sig_path and os.path.exists(sig_path) and os.access(sig_path, os.R_OK):
            try:
                with PILImage.open(sig_path) as img:
                    img.verify()
                sig_img = RLImage(sig_path, width=3*cm, height=1.5*cm)
                sig_img.hAlign = 'LEFT'
            except Exception as e:
                logger.error(f"Error loading signature: {str(e)}")

        stamp_path = source_doc.extracted_stamp.path if source_doc.extracted_stamp else None
        if stamp_path and os.path.exists(stamp_path) and os.access(stamp_path, os.R_OK):
            try:
                with PILImage.open(stamp_path) as img:
                    img.verify()
                stamp_img = RLImage(stamp_path, width=2.5*cm, height=2.5*cm)
                stamp_img.hAlign = 'RIGHT'
            except Exception as e:
                logger.error(f"Error loading stamp: {str(e)}")

    # Header (adapted for merged)
    header_elements = []
    header_text = display.header if display else f"Merged Results for {class_names} - {examination_name.exam_name}"
    header_elements.append(Paragraph(header_text, header_style))
    header_elements.append(Spacer(1, 4))
    header_elements.append(Paragraph(display.body if display else f"Comprehensive Merged Academic Summary - {class_names}", subheader_style))
    header_elements.append(Spacer(1, 8))

    if icon:
        header_elements.append(icon)
        header_elements.append(Spacer(1, 0.5*cm))

    elements.extend(header_elements)

    current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    process = psutil.Process()
    logger.debug(f"Memory usage at start: {process.memory_info().rss / 1024 / 1024:.2f} MB")

    if not students.exists() or not subjects.exists():
        no_data_style = ParagraphStyle(
            name='NoData',
            parent=styles['BodyText'],
            fontSize=10,
            textColor=colors.red,
            alignment=TA_CENTER,
            spaceAfter=12,
            fontName='Helvetica-Bold'
        )
        elements.append(Paragraph("No academic data available for selected classes.", no_data_style))
    else:
        students_marks_evaluation = Student.objects.filter(teacherclass__in=teacherclasses).annotate(
            total_marks=Sum('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination_name)),
            average_marks=Avg('marks__marks', filter=Q(marks__subject__in=subjects, marks__examinationname=examination_name))
        ).select_related('teacherclass')

        student_data = []
        for student in students_marks_evaluation:
            total_marks = student.total_marks or 0
            average_marks = student.average_marks or 0
            student_marks_dict = {m.subject_id: m.marks for m in student.marks.all()}
            marks_list = []
            grades_for_division = []

            # Build marks_list
            for subj in subjects_list:
                subj_id = subj['id']
                if subj_id == 'composite':
                    component_marks = [student_marks_dict.get(cid) for cid in component_ids_set if student_marks_dict.get(cid) is not None]
                    if component_marks:
                        avg_mark = sum(component_marks) / len(component_marks)
                        grade = get_grade(avg_mark)
                        component_marks_objs = [m for m in student.marks.all() if m.subject_id in component_ids_set]
                        teacher_names = {teacher_map.get(m.user_id, m.user.username) for m in component_marks_objs if m.user_id}
                        teacher_name = ', '.join(sorted(teacher_names)) or '-'
                        marks_list.append({
                            'subject_id': subj_id,
                            'subject_name': subj['nameSubject'],
                            'mark': avg_mark,
                            'grade': grade,
                            'is_excluded': False,
                            'teacher_name': teacher_name
                        })
                    else:
                        marks_list.append({
                            'subject_id': subj_id,
                            'subject_name': subj['nameSubject'],
                            'mark': None,
                            'grade': '-',
                            'is_excluded': False,
                            'teacher_name': '-'
                        })
                else:
                    mark_value = student_marks_dict.get(int(subj_id))
                    grade = get_grade(mark_value)
                    mark_obj = student.marks.filter(subject_id=int(subj_id), examinationname=examination_name).first()
                    teacher_name = teacher_map.get(mark_obj.user_id, '-') if mark_obj and mark_obj.user_id else '-'
                    is_excluded = int(subj_id) in exclude_subjects
                    marks_list.append({
                        'subject_id': int(subj_id),
                        'subject_name': subj['nameSubject'],
                        'mark': mark_value,
                        'grade': grade,
                        'is_excluded': is_excluded,
                        'teacher_name': teacher_name
                    })

            # Build grades_for_division with composite logic
            if grading.is_advance and composite and component_ids_set:
                if composite.allow_to_use:
                    # Composite already in marks_list as one
                    pass
                else:
                    # Add averaged grade for component group
                    component_marks_values = [mi['mark'] for mi in marks_list if mi['subject_id'] in component_ids_set and mi['mark'] is not None]
                    if component_marks_values:
                        avg_mark_comp = sum(component_marks_values) / len(component_marks_values)
                        avg_grade_comp = get_grade(avg_mark_comp)
                        grades_for_division.append(avg_grade_comp)

            for mark_info in marks_list:
                subj_id = mark_info['subject_id']
                if subj_id == 'composite' or (not component_ids_set or subj_id not in component_ids_set):
                    if not mark_info['is_excluded'] and mark_info['grade'] != '-':
                        grades_for_division.append(mark_info['grade'])

            division, total_points = get_division(grades_for_division)

            student_data.append({
                'id': student.id,
                'fullName': student.fullName or 'Unnamed Student',
                'sex': student.sex or '-',
                'indexNumber': student.indexNumber or '-',
                'class_name': student.teacherclass.ClassName.class_name,  # Added class name
                'marks': marks_list,
                'total_marks': total_marks,
                'average_marks': average_marks,
                'grade': get_grade(average_marks),
                'division': division,
                'total_points': total_points,
                'has_valid_marks': any(grade != '-' for grade in grades_for_division)
            })

        # Sort students: complete first, then by average descending
        student_data.sort(key=lambda x: (-x['has_valid_marks'], -x['average_marks']))

        # CLASS PERFORMANCE SUMMARY section (add Class column)
        elements.append(Paragraph("Merged Academic Results", subheader_style))

        # Build multi-level header with Class column
        header_row1 = [
            'Pos', 
            'Student Name', 
            'Sex', 
            'Class',  # New column
            'Index No'
        ]
        for s in subjects_list:
            header_row1.append(s['nameSubject'])
            header_row1.append('')  # Placeholder for span

        header_row1 += ['Total', 'Avg', 'Grade']
        if not grading.is_primary:
            header_row1 += ['Div', 'Pts']

        header_row2 = ['', '', '', '', '']  # Empty for first five columns
        for _ in subjects_list:
            header_row2.append('M')
            header_row2.append('G')
        header_row2 += ['', '', '']
        if not grading.is_primary:
            header_row2 += ['', '']

        table_data = [header_row1, header_row2]

        # Add spans for subject names in header_row1
        subject_start_col = 5  # Shifted by 1 for Class
        table_style_commands = [
            ('SPAN', (0, 0), (0, 1)),  # Pos
            ('SPAN', (1, 0), (1, 1)),  # Name
            ('SPAN', (2, 0), (2, 1)),  # Sex
            ('SPAN', (3, 0), (3, 1)),  # Class
            ('SPAN', (4, 0), (4, 1)),  # Index
        ]
        for i in range(len(subjects_list)):
            start_col = subject_start_col + i * 2
            table_style_commands.append(('SPAN', (start_col, 0), (start_col + 1, 0)))  # Subject spans two columns

        total_columns = len(header_row1)
        subject_end_col = subject_start_col + len(subjects_list) * 2 - 1
        table_style_commands += [
            ('SPAN', (subject_end_col + 1, 0), (subject_end_col + 1, 1)),  # Total
            ('SPAN', (subject_end_col + 2, 0), (subject_end_col + 2, 1)),  # Avg
            ('SPAN', (subject_end_col + 3, 0), (subject_end_col + 3, 1)),  # Grade
        ]
        if not grading.is_primary:
            table_style_commands += [
                ('SPAN', (subject_end_col + 4, 0), (subject_end_col + 4, 1)),  # Div
                ('SPAN', (subject_end_col + 5, 0), (subject_end_col + 5, 1)),  # Pts
            ]

        for i, student in enumerate(student_data, 1):
            row = [
                str(i), 
                student['fullName'], 
                student['sex'], 
                student['class_name'],  # New: Class
                student['indexNumber']
            ]
            for subj in subjects_list:
                mark_info = next((m for m in student['marks'] if m['subject_id'] == subj['id']), None)
                if mark_info and mark_info['mark'] is not None:
                    mark_str = f"{mark_info['mark']}"
                    grade = mark_info['grade']
                else:
                    mark_str = '-'
                    grade = '-'
                row.append(mark_str)
                row.append(grade)
            row.extend([
                f"{student['total_marks']:.2f}" if student['total_marks'] > 0 else '-',
                f"{student['average_marks']:.2f}" if student['average_marks'] > 0 else '-',
                student['grade'],
            ])
            if not grading.is_primary:
                row.extend([
                    student['division'],
                    str(student['total_points']) if student['total_points'] != '-' else '-'
                ])
            table_data.append(row)

        # Calculate column widths (adjusted for extra Class column)
        available_width = A4[0] - 30
        base_width = available_width / (5 + len(subjects_list) * 2 + 3 + (2 if not grading.is_primary else 0))  # +1 for Class
        col_widths = (
            [base_width * 0.5] +  # Pos
            [base_width * 2] +  # Name (slightly reduced)
            [base_width * 0.5] +  # Sex
            [base_width * 1.5] +  # Class
            [base_width * 1.2] +  # Index (reduced)
            [base_width * 0.45, base_width * 0.45] * len(subjects_list) +  # Mark, Grade
            [base_width * 0.8] * 3  # Total, Avg, Grade
        )
        if not grading.is_primary:
            col_widths += [base_width * 0.6] * 2  # Div, Pts

        summary_table = Table(table_data, colWidths=col_widths, repeatRows=2)
        summary_table_style = TableStyle([
            ('GRID', (0, 0), (-1, -1), 0.5, colors.black),
            ('BACKGROUND', (0, 0), (-1, 1), colors.lightgrey),
            ('FONTNAME', (0, 0), (-1, 1), 'Helvetica-Bold'),
            ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
            ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
            ('FONTSIZE', (0, 0), (-1, -1), 5),
            ('LEADING', (0, 0), (-1, -1), 6),
            ('BOX', (0, 0), (-1, -1), 1, colors.black),
            ('LEFTPADDING', (0, 0), (-1, -1), 4),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),
            ('TOPPADDING', (0, 0), (-1, -1), 4),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
        ] + table_style_commands)

        # Apply grade colors per cell
        for row_idx, row in enumerate(table_data[2:], start=2):  # Start from body rows
            for subj_idx in range(len(subjects_list)):
                grade_col = 5 + subj_idx * 2 + 1  # Adjusted for Class column
                grade = row[grade_col]
                color = get_grade_color(grade)
                summary_table_style.add('TEXTCOLOR', (grade_col, row_idx), (grade_col, row_idx), color)
                summary_table_style.add('FONTNAME', (grade_col, row_idx), (grade_col, row_idx), 'Helvetica-Bold')

        summary_table.setStyle(summary_table_style)
        elements.append(KeepTogether(summary_table))
        elements.append(Spacer(1, 10))

        # Individual Student Reports (same as original, but with class already included)
        total_students = len(student_data)

        for i, student in enumerate(student_data, 1):
            elements.append(PageBreak())

            # Individual report header (adapted)
            individual_header = []

            # Header with school logo and info
